// Northwind soruları. w01–w24: eğitimden gelen Late Shipment soruları (kontrol edilebilir çıktı tanımıyla),
// w25–w40: SorguLab ek soruları (hiyerarşi, stok, tedarikçi, sepet analizi, trend, pandas).
// Tablo adları SQL Server'daki gibi; tek fark "Order Details" → OrderDetails.
const NW_LR = "ROUND(100.0 * AVG(CASE WHEN o.ShippedDate > o.RequiredDate THEN 1 ELSE 0 END), 2)";
const NW_LRN = "ROUND(100.0 * AVG(CASE WHEN o.ShippedDate IS NULL THEN NULL WHEN o.ShippedDate > o.RequiredDate THEN 1 ELSE 0 END), 2)";
const NW_TUTAR = "SELECT OrderID, SUM(UnitPrice * Quantity * (1 - Discount)) AS tutar FROM OrderDetails GROUP BY OrderID";
const NW_TANIM = '<p class="kucuk">Tanımlar: <b>geç gönderim</b> = <code>ShippedDate &gt; RequiredDate</code>. Late Shipment Rate sadece <b>gönderilmiş</b> siparişler (<code>ShippedDate IS NOT NULL</code>) üzerinden hesaplanır, yüzde ve 2 ondalık. <b>Sipariş tutarı</b> = <code>SUM(UnitPrice * Quantity * (1 - Discount))</code> (OrderDetails).</p>';
const NW_GRUP = "CASE WHEN t.tutar < 500 THEN 'Küçük' WHEN t.tutar < 1500 THEN 'Orta' WHEN t.tutar < 3000 THEN 'Büyük' ELSE 'Çok büyük' END";
const NW_SQLSERVER_TARIH = '<p><b>SQL Server notu:</b> Gün farkı SQL Server\'da <code>DATEDIFF(day, OrderDate, ShippedDate)</code>, yıl <code>YEAR(OrderDate)</code> ile alınır. Burada SQLite\'ın <code>julianday()</code> ve <code>strftime()</code> fonksiyonları kullanılıyor.</p>';

const NW_SORULAR = [
  // ───────── Geç gönderim: genel tablo ─────────
  { id: 'w01', dil: 'sql', seviye: 1, kategori: 'Aggregation', baslik: 'Genel Late Shipment Rate',
    soru: '<p>Toplam sipariş sayısını, gönderilmiş sipariş sayısını, geciken sipariş sayısını ve genel Late Shipment Rate değerini hesapla.</p>' + NW_TANIM + '<p>Beklenen çıktı: tek satır, <code>toplam_siparis</code>, <code>gonderilen</code>, <code>geciken</code>, <code>late_rate</code>.</p>',
    ipucu: 'Gönderilmiş siparişleri <code>COUNT(ShippedDate)</code> sayar (NULL\'ları atlar). Geç gönderim oranının paydası da bu olmalı.',
    cozum: "SELECT COUNT(*) AS toplam_siparis,\n       COUNT(ShippedDate) AS gonderilen,\n       SUM(CASE WHEN ShippedDate > RequiredDate THEN 1 ELSE 0 END) AS geciken,\n       ROUND(100.0 * SUM(CASE WHEN ShippedDate > RequiredDate THEN 1 ELSE 0 END) / COUNT(ShippedDate), 2) AS late_rate\nFROM Orders;",
    aciklama: '<p>830 siparişin 21\'i henüz gönderilmemiş. Bunları oranın paydasına katarsan oran yapay olarak düşer, çünkü gönderilmemiş bir siparişin geç mi zamanında mı gittiği henüz bilinmiyor.</p><p><code>COUNT(sütun)</code> NULL\'ları saymaz. Bu yüzden <code>COUNT(ShippedDate)</code> doğrudan gönderilmiş sipariş sayısını verir. <code>ShippedDate &gt; RequiredDate</code> karşılaştırması NULL olduğunda sonuç NULL olur ve CASE onu ELSE\'e (0) düşürür, ama paydada olmadığı için oranı bozmaz.</p><p>Tarihler ISO formatında (YYYY-MM-DD) saklandığı için metin karşılaştırması tarih karşılaştırmasıyla aynı sonucu verir.</p>' },
  { id: 'w02', dil: 'sql', seviye: 2, kategori: 'Tarih', baslik: 'Yıllara göre Late Shipment Rate', sirali: true,
    soru: '<p>Yıllara göre sipariş sayısını ve Late Shipment Rate değerini karşılaştır.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>yil</code> (sipariş yılı), <code>siparis</code> (tüm siparişler), <code>gonderilen</code>, <code>late_rate</code>. Yıla göre sırala.</p>',
    ipucu: '<code>strftime(\'%Y\', OrderDate)</code>. Gönderilmemişleri oranın dışında tutmak için CASE\'te NULL döndür.',
    cozum: `SELECT strftime('%Y', o.OrderDate) AS yil,\n       COUNT(*) AS siparis,\n       COUNT(o.ShippedDate) AS gonderilen,\n       ${NW_LRN} AS late_rate\nFROM Orders o\nGROUP BY yil\nORDER BY yil;`,
    aciklama: '<p>Tek sorguda hem tüm siparişleri hem de sadece gönderilmişlerin oranını hesaplamak için CASE\'in ilk dalı gönderilmemişlere <code>NULL</code> verir. AVG NULL\'ları atladığı için oran sadece gönderilmişler üzerinden hesaplanır, COUNT(*) ise hepsini sayar.</p><p>1998 verisi Mayıs ayında bitiyor ve gönderilmemiş 21 siparişin hepsi bu yılda. Yıllar arası karşılaştırmada eksik yıl ve "henüz kapanmamış" siparişler mutlaka belirtilmeli.</p>' + NW_SQLSERVER_TARIH },
  { id: 'w03', dil: 'sql', seviye: 2, kategori: 'Aggregation', baslik: 'Ülkeye göre Late Shipment Rate', sirali: true,
    soru: '<p>Gönderim ülkesine (<code>ShipCountry</code>) göre Late Shipment Rate hesapla.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>ShipCountry</code>, <code>gonderilen</code>, <code>geciken</code>, <code>late_rate</code>. Oranı en yüksek ülke en üstte, eşitlikte ülke adına göre.</p>',
    ipucu: 'Önce <code>WHERE ShippedDate IS NOT NULL</code> ile süz, sonra ülkeye göre grupla.',
    cozum: `SELECT o.ShipCountry,\n       COUNT(*) AS gonderilen,\n       SUM(CASE WHEN o.ShippedDate > o.RequiredDate THEN 1 ELSE 0 END) AS geciken,\n       ${NW_LR} AS late_rate\nFROM Orders o\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY o.ShipCountry\nORDER BY late_rate DESC, o.ShipCountry;`,
    aciklama: '<p>Burada filtreyi WHERE ile yapmak en temiz yol: oranın paydası zaten gönderilmiş siparişler.</p><p>21 ülkenin birçoğunda hiç geç gönderim yok ve en yüksek oranlar birkaç siparişe dayanıyor. Bu yüzden eşitlik bozan ikinci sıralama kriteri (ülke adı) şart. Yorumlarken <code>geciken</code> sütununa bak: %20\'lik bir oran 2 siparişten de 20 siparişten de gelebilir.</p>' },
  { id: 'w04', dil: 'sql', seviye: 2, kategori: 'CASE WHEN', baslik: 'Sipariş tutarı gruplarına göre', sirali: true,
    soru: '<p>Sipariş tutarını anlamlı gruplara ayırarak Late Shipment Rate değerlerini karşılaştır.</p><p>Gruplar: 500\'den az <code>Küçük</code>, 500-1499 <code>Orta</code>, 1500-2999 <code>Büyük</code>, 3000 ve üzeri <code>Çok büyük</code>.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>tutar_grubu</code>, <code>gonderilen</code>, <code>late_rate</code>. Küçükten büyüğe sırala.</p>',
    ipucu: 'Sipariş tutarını bir CTE\'de hesapla, Orders ile JOIN\'le, sonra CASE ile grupla. Sıralama için <code>ORDER BY MIN(t.tutar)</code>.',
    cozum: `WITH t AS (\n  ${NW_TUTAR}\n)\nSELECT ${NW_GRUP} AS tutar_grubu,\n       COUNT(*) AS gonderilen,\n       ${NW_LR} AS late_rate\nFROM Orders o\nJOIN t ON t.OrderID = o.OrderID\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY tutar_grubu\nORDER BY MIN(t.tutar);`,
    aciklama: '<p>Sipariş tutarı OrderDetails\'te satır satır duruyor. Önce sipariş bazında toplayıp (CTE), sonra sipariş tablosuyla birleştirmek gerekiyor. Doğrudan Orders ile OrderDetails\'i JOIN\'leyip gruplasaydın her sipariş satır sayısı kadar çoğalırdı ve oran ağırlıklı olarak bozulurdu (fan-out).</p><p>En yüksek oran "Çok büyük" grupta (%6,7), ama ilişki düzgün artmıyor: Orta grubun oranı Büyük gruptan yüksek. Ayrıca "Çok büyük" gruptaki oran 90 siparişte 6 gecikmeye dayanıyor. Yorumda bu küçüklüğü belirt.</p><p><b>SQL Server notu:</b> Orada tablo adı <code>[Order Details]</code>. Boşluk içerdiği için köşeli parantez şart.</p>' },
  { id: 'w05', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'Çalışan performansı', sirali: true,
    soru: '<p>Çalışanların yönettiği siparişlerde sipariş sayısı, satış tutarı ve Late Shipment Rate değerini karşılaştır.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>calisan</code> (<code>FirstName || \' \' || LastName</code>), <code>siparis</code> (tüm siparişler), <code>satis</code> (2 ondalık), <code>late_rate</code> (gönderilmişler üzerinden). Satışı en yüksek çalışan en üstte.</p>',
    ipucu: 'Employees → Orders → sipariş tutarı CTE\'si. Oranda gönderilmemiş siparişleri NULL yaparak dışarıda bırak.',
    cozum: `WITH t AS (\n  ${NW_TUTAR}\n)\nSELECT e.FirstName || ' ' || e.LastName AS calisan,\n       COUNT(*) AS siparis,\n       ROUND(SUM(t.tutar), 2) AS satis,\n       ${NW_LRN} AS late_rate\nFROM Employees e\nJOIN Orders o ON o.EmployeeID = e.EmployeeID\nJOIN t ON t.OrderID = o.OrderID\nGROUP BY e.EmployeeID, calisan\nORDER BY satis DESC;`,
    aciklama: '<p>Üç tabloyu birleştiriyoruz: çalışan, sipariş ve sipariş tutarı. Tutar CTE\'si sipariş başına tek satır olduğu için JOIN satır sayısını artırmıyor.</p><p>Satış ve sipariş sayısı tüm siparişler üzerinden, oran ise sadece gönderilmişler üzerinden hesaplanıyor. Bunu tek GROUP BY\'da yapmanın yolu CASE\'te gönderilmemişlere NULL vermek.</p><p><b>SQL Server notu:</b> Metin birleştirme <code>||</code> yerine <code>+</code> ya da <code>CONCAT(FirstName, \' \', LastName)</code> ile yapılır.</p>' },

  // ───────── Müşteri ve sipariş profili ─────────
  { id: 'w06', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'En sık sipariş veren müşteriler', sirali: true,
    soru: '<p>Müşterilerin sipariş sıklığını, ortalama sipariş tutarını ve Late Shipment Rate değerini incele.</p>' + NW_TANIM + '<p>Beklenen çıktı: en çok sipariş veren 10 müşteri. <code>CustomerID</code>, <code>CompanyName</code>, <code>siparis</code>, <code>ort_tutar</code> (2 ondalık), <code>late_rate</code> (gönderilmişler üzerinden). Sipariş sayısına göre azalan, eşitlikte CustomerID.</p>',
    ipucu: 'Customers → Orders → tutar CTE\'si; <code>ORDER BY siparis DESC, CustomerID LIMIT 10</code>.',
    cozum: `WITH t AS (\n  ${NW_TUTAR}\n)\nSELECT c.CustomerID, c.CompanyName,\n       COUNT(*) AS siparis,\n       ROUND(AVG(t.tutar), 2) AS ort_tutar,\n       ${NW_LRN} AS late_rate\nFROM Customers c\nJOIN Orders o ON o.CustomerID = c.CustomerID\nJOIN t ON t.OrderID = o.OrderID\nGROUP BY c.CustomerID, c.CompanyName\nORDER BY siparis DESC, c.CustomerID\nLIMIT 10;`,
    aciklama: '<p>"Sipariş sıklığı" burada toplam sipariş sayısı. Zamana bölünmüş bir sıklık (ayda kaç sipariş) için ilk ve son sipariş tarihi arasındaki süre de hesaba katılabilir.</p><p>En sadık müşteriler arasında bile geç gönderim yaşayanlar var. Sık sipariş veren bir müşteride tekrarlayan gecikme, müşteri kaybı riski açısından tek seferlik müşteriden daha önemli.</p><p><b>SQL Server notu:</b> <code>LIMIT 10</code> yerine <code>SELECT TOP 10</code>.</p>' },
  { id: 'w07', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'Müşteri ülkesi = gönderim ülkesi mi?',
    soru: '<p>Müşteri ülkesi ile gönderim ülkesini birlikte analiz et.</p><p>Bu analizin ilk adımı bir varsayımı doğrulamak: siparişler her zaman müşterinin kendi ülkesine mi gönderiliyor? Beklenen çıktı: tek satır, <code>toplam_siparis</code>, <code>ayni_ulke</code>, <code>farkli_ulke</code>.</p>',
    ipucu: 'Orders ile Customers\'ı birleştir, <code>c.Country = o.ShipCountry</code> karşılaştırmasını CASE ile say.',
    cozum: "SELECT COUNT(*) AS toplam_siparis,\n       SUM(CASE WHEN c.Country = o.ShipCountry THEN 1 ELSE 0 END) AS ayni_ulke,\n       SUM(CASE WHEN c.Country <> o.ShipCountry THEN 1 ELSE 0 END) AS farkli_ulke\nFROM Orders o\nJOIN Customers c ON c.CustomerID = o.CustomerID;",
    aciklama: '<p>Sonuç: 830 siparişin hepsi müşterinin kendi ülkesine gönderilmiş. Yani bu veride "müşteri ülkesi × gönderim ülkesi" kırılımı yeni bir bilgi vermiyor, iki sütun aynı şeyi söylüyor.</p><p>Bu da değerli bir bulgu. Çapraz tablo kurmadan önce varsayımı tek bir sorguyla test etmek, boş ya da anlamsız bir analizle zaman kaybetmeyi önler. Raporda "müşteri ve gönderim ülkesi tüm siparişlerde aynı olduğundan analizde ShipCountry kullanıldı" demek yeterli.</p>' },
  { id: 'w08', dil: 'sql', seviye: 3, kategori: 'Window Functions', baslik: 'İlk siparişlerde geç gönderim', sirali: true,
    soru: '<p>Müşterilerin ilk siparişlerinde Late Shipment Rate değerini hesapla ve diğer siparişlerle karşılaştır.</p>' + NW_TANIM + '<p>İlk sipariş = müşterinin en erken <code>OrderDate</code>\'li siparişi (aynı gün birden fazlaysa küçük OrderID). Beklenen çıktı: <code>grup</code> (<code>İlk sipariş</code> / <code>Diğer</code>), <code>gonderilen</code>, <code>late_rate</code>. Önce İlk sipariş.</p>',
    ipucu: '<code>ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY OrderDate, OrderID)</code> = 1 olanlar ilk sipariş.',
    cozum: `WITH s AS (\n  SELECT o.*,\n         ROW_NUMBER() OVER (PARTITION BY o.CustomerID ORDER BY o.OrderDate, o.OrderID) AS rn\n  FROM Orders o\n)\nSELECT CASE WHEN rn = 1 THEN 'İlk sipariş' ELSE 'Diğer' END AS grup,\n       COUNT(*) AS gonderilen,\n       ${NW_LR} AS late_rate\nFROM s o\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY grup\nORDER BY MIN(rn);`,
    aciklama: '<p>Önce tüm siparişleri müşteri bazında numaralandırıyoruz, <b>sonra</b> gönderilmemişleri eliyoruz. Sıra önemli: önce filtreleyip sonra numaralandırsaydın, ilk siparişi henüz gönderilmemiş bir müşterinin ikinci siparişi yanlışlıkla "ilk sipariş" sayılırdı.</p><p>Sonuç beklentinin tersi: ilk siparişlerde oran daha <b>düşük</b> (%3,4\'e karşı %4,7). Ama 89 ilk siparişte sadece 3 gecikme var. Bu kadar küçük bir sayıyla "ilk siparişlere özen gösteriliyor" demek için kanıt yetersiz.</p><p>Analist dersi: hipotezi ("ilk siparişler daha riskli olmalı") veriyle test etmeden yönetici özetine yazmamak. Bazen veri beklentini doğrulamaz, bu da bir bulgudur.</p>' },

  // ───────── Ürün ve satış performansı ─────────
  { id: 'w09', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'Kategori bazında satış', sirali: true,
    soru: '<p>Kategori bazında satış tutarı, satılan miktar ve sipariş sayısını incele.</p><p>Beklenen çıktı: <code>CategoryName</code>, <code>satis</code> (2 ondalık), <code>miktar</code>, <code>siparis</code> (o kategoriden ürün içeren farklı sipariş sayısı). Satışı en yüksek kategori en üstte.</p>',
    ipucu: 'OrderDetails → Products → Categories. Sipariş sayısı için <code>COUNT(DISTINCT od.OrderID)</code>.',
    cozum: "SELECT c.CategoryName,\n       ROUND(SUM(od.UnitPrice * od.Quantity * (1 - od.Discount)), 2) AS satis,\n       SUM(od.Quantity) AS miktar,\n       COUNT(DISTINCT od.OrderID) AS siparis\nFROM OrderDetails od\nJOIN Products p ON p.ProductID = od.ProductID\nJOIN Categories c ON c.CategoryID = p.CategoryID\nGROUP BY c.CategoryName\nORDER BY satis DESC;",
    aciklama: '<p>Satış fiyatı olarak <code>OrderDetails.UnitPrice</code> kullanılıyor, <code>Products.UnitPrice</code> değil. Sipariş anındaki fiyat sipariş satırında saklanıyor, ürün tablosundaki fiyat ise güncel liste fiyatı. Northwind\'de 77 ürünün hepsinde, en az bir siparişteki fiyat güncel liste fiyatından farklı. Yanlış tabloyu kullanmak geçmiş satışları güncel fiyatla hesaplamak olur.</p><p><code>COUNT(*)</code> satır sayısını (sipariş kalemi) verirdi. Bir sipariş aynı kategoriden birden fazla ürün içerebildiği için sipariş sayısında <code>DISTINCT</code> şart.</p>' },
  { id: 'w10', dil: 'sql', seviye: 3, kategori: 'Subquery / CTE', baslik: 'Kategori bazında Late Shipment Rate', sirali: true,
    soru: '<p>Kategori bazında Late Shipment Rate hesapla.</p>' + NW_TANIM + '<p>Bir sipariş birden fazla kategoriden ürün içerebilir. Her sipariş, içinde ürünü bulunan her kategoride <b>bir kez</b> sayılsın. Beklenen çıktı: <code>CategoryName</code>, <code>gonderilen</code>, <code>late_rate</code>. Oranı en yüksek en üstte, eşitlikte kategori adına göre.</p>',
    ipucu: 'Önce <code>SELECT DISTINCT OrderID, CategoryID</code> ile sipariş-kategori çiftlerini çıkar, sonra Orders ile birleştir.',
    cozum: `WITH sk AS (\n  SELECT DISTINCT od.OrderID, p.CategoryID\n  FROM OrderDetails od\n  JOIN Products p ON p.ProductID = od.ProductID\n)\nSELECT c.CategoryName,\n       COUNT(*) AS gonderilen,\n       ${NW_LR} AS late_rate\nFROM sk\nJOIN Orders o ON o.OrderID = sk.OrderID\nJOIN Categories c ON c.CategoryID = sk.CategoryID\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY c.CategoryName\nORDER BY late_rate DESC, c.CategoryName;`,
    aciklama: '<p>Geç gönderim sipariş seviyesinde bir olay, kategori ise ürün seviyesinde. İki seviyeyi birleştirirken tuzak şu: OrderDetails ile doğrudan JOIN yaparsan, aynı kategoriden 3 ürün içeren geç bir sipariş o kategoride 3 kez geç sayılır.</p><p><code>DISTINCT OrderID, CategoryID</code> bu çoğalmayı önler. Granülariteyi (her satır neyi temsil ediyor?) sorgu kurmadan önce netleştirmek, analistlerin en çok atladığı adımlardan biri.</p>' },
  { id: 'w11', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'En çok satan 10 ürün', sirali: true,
    soru: '<p>Ürün bazında satış tutarı ve satış miktarını inceleyip en yüksek satışa sahip ilk 10 ürünü bul.</p><p>Beklenen çıktı: <code>ProductName</code>, <code>satis</code> (2 ondalık), <code>miktar</code>. Satışa göre azalan.</p>',
    ipucu: 'OrderDetails ile Products\'ı birleştir, ürüne göre grupla, <code>LIMIT 10</code>.',
    cozum: "SELECT p.ProductName,\n       ROUND(SUM(od.UnitPrice * od.Quantity * (1 - od.Discount)), 2) AS satis,\n       SUM(od.Quantity) AS miktar\nFROM OrderDetails od\nJOIN Products p ON p.ProductID = od.ProductID\nGROUP BY p.ProductID, p.ProductName\nORDER BY satis DESC\nLIMIT 10;",
    aciklama: '<p>Satış tutarı ile satış miktarı farklı sıralamalar verir. Listenin başındaki Côte de Blaye pahalı bir ürün, miktar olarak çok satmadan tutarda zirvede. Hangi metriğin önemli olduğu soruya bağlı: gelir mi, operasyon yükü mü?</p><p>GROUP BY\'a ProductID\'yi de koymak iyi bir alışkanlık. Aynı isimli iki ürün olsaydı sadece isme göre gruplamak onları birleştirirdi.</p>' },
  { id: 'w12', dil: 'sql', seviye: 3, kategori: 'CASE WHEN', baslik: 'İndirim gruplarına göre', sirali: true,
    soru: '<p>İndirim gruplarına göre satış tutarı ve Late Shipment Rate değerini karşılaştır.</p>' + NW_TANIM + '<p>İndirim grubu sipariş seviyesinde belirlensin: siparişteki <b>en yüksek</b> indirim 0 ise <code>İndirimsiz</code>, %10 ve altıysa <code>Düşük</code>, üstüyse <code>Yüksek</code>. Beklenen çıktı: <code>indirim_grubu</code>, <code>siparis</code> (tüm siparişler), <code>satis</code> (2 ondalık), <code>late_rate</code> (gönderilmişler üzerinden). İndirimsizden yükseğe sırala.</p>',
    ipucu: 'Sipariş başına <code>MAX(Discount)</code> ve tutarı bir CTE\'de hesapla.',
    cozum: `WITH s AS (\n  SELECT OrderID,\n         MAX(Discount) AS max_ind,\n         SUM(UnitPrice * Quantity * (1 - Discount)) AS tutar\n  FROM OrderDetails\n  GROUP BY OrderID\n)\nSELECT CASE WHEN s.max_ind = 0 THEN 'İndirimsiz'\n            WHEN s.max_ind <= 0.10 THEN 'Düşük'\n            ELSE 'Yüksek' END AS indirim_grubu,\n       COUNT(*) AS siparis,\n       ROUND(SUM(s.tutar), 2) AS satis,\n       ${NW_LRN} AS late_rate\nFROM s\nJOIN Orders o ON o.OrderID = s.OrderID\nGROUP BY indirim_grubu\nORDER BY MIN(s.max_ind);`,
    aciklama: '<p>İndirim satır seviyesinde, geç gönderim sipariş seviyesinde. Bir siparişi tek bir indirim grubuna koymak için bir kural seçmek gerekiyor. Burada "en yüksek indirim" seçildi. Alternatif: ortalama indirim, ya da indirimli satır var mı yok mu.</p><p><code>REAL</code> tipindeki indirim değerlerinde <code>&lt;= 0.10</code> karşılaştırması güvenli, çünkü veride 0.1 tam olarak saklanıyor. Hesaplanmış ondalıklarla eşitlik karşılaştırması yaparken yuvarlama hatalarına dikkat etmek gerekir.</p>' },
  { id: 'w13', dil: 'sql', seviye: 2, kategori: 'Tarih', baslik: 'Sevkiyat süresi ve navlun özeti',
    soru: '<p>Siparişlerin ortalama sevkiyat süresini, ortalama Freight değerini ve genel Late Shipment Rate değerini hesapla.</p>' + NW_TANIM + '<p>Sevkiyat süresi = <code>ShippedDate − OrderDate</code> (gün). Hepsi gönderilmiş siparişler üzerinden. Beklenen çıktı: tek satır, <code>ort_sevk_gun</code>, <code>ort_navlun</code>, <code>late_rate</code> (hepsi 2 ondalık).</p>',
    ipucu: '<code>julianday(ShippedDate) - julianday(OrderDate)</code>',
    cozum: `SELECT ROUND(AVG(julianday(o.ShippedDate) - julianday(o.OrderDate)), 2) AS ort_sevk_gun,\n       ROUND(AVG(o.Freight), 2) AS ort_navlun,\n       ${NW_LR} AS late_rate\nFROM Orders o\nWHERE o.ShippedDate IS NOT NULL;`,
    aciklama: '<p>Ortalama sevkiyat süresi 8,5 gün civarında. Ama siparişlerin büyük çoğunluğunda istenen teslim süresi 28 gün. Yani ortalama sevkiyat hızı sorun değil, sorun dağılımın kuyruğunda (15. soru).</p><p>Ortalama gibi tek bir sayı, geç gönderim gibi nadir olayları gizleyebilir. "Ortalama 8,5 gün" iyi görünür, ama siparişlerin yaklaşık %7\'sinin 3 haftadan uzun sürmesi o müşteriler açısından asıl deneyimdir.</p>' + NW_SQLSERVER_TARIH },
  { id: 'w14', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'Taşıyıcı karşılaştırması', sirali: true,
    soru: '<p>Taşıyıcı (Shipper) bazında sipariş sayısı, ortalama Freight ve Late Shipment Rate değerini karşılaştır.</p>' + NW_TANIM + '<p>Gönderilmiş siparişler üzerinden. Beklenen çıktı: <code>CompanyName</code>, <code>gonderilen</code>, <code>ort_navlun</code> (2 ondalık), <code>late_rate</code>. Oranı en yüksek en üstte.</p>',
    ipucu: '<code>Orders.ShipVia = Shippers.ShipperID</code>',
    cozum: `SELECT s.CompanyName,\n       COUNT(*) AS gonderilen,\n       ROUND(AVG(o.Freight), 2) AS ort_navlun,\n       ${NW_LR} AS late_rate\nFROM Orders o\nJOIN Shippers s ON s.ShipperID = o.ShipVia\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY s.CompanyName\nORDER BY late_rate DESC;`,
    aciklama: '<p>JOIN anahtarlarının adı her zaman aynı olmuyor: Orders\'taki <code>ShipVia</code>, Shippers\'taki <code>ShipperID</code>\'yi gösteriyor. Şemayı okumadan JOIN yazmak bu tür ilişkileri kaçırmaya yol açar.</p><p>Taşıyıcılar arasındaki fark küçük (en yüksek ile en düşük arasında yaklaşık 1,5 puan) ve her birinde 9 ile 16 arasında geç gönderim var. Bu farkla "X taşıyıcıyı bırakalım" demek için veri yetersiz. 21. soruda bunu genel orandan sapma olarak göreceksin.</p>' },
  { id: 'w15', dil: 'sql', seviye: 2, kategori: 'CASE WHEN', baslik: 'Sevkiyat süresi grupları', sirali: true,
    soru: '<p>Sevkiyat süresini gruplara ayırıp Late Shipment Rate değerlerini karşılaştır.</p><p>Gruplar (gün): <code>0-7</code>, <code>8-14</code>, <code>15-21</code>, <code>22+</code>.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>sure_grubu</code>, <code>gonderilen</code>, <code>geciken</code>, <code>late_rate</code>. Kısadan uzuna sırala.</p>',
    ipucu: 'Sevkiyat süresini bir CTE\'de hesapla, CASE ile grupla, <code>ORDER BY MIN(gun)</code>.',
    cozum: `WITH s AS (\n  SELECT o.*, julianday(o.ShippedDate) - julianday(o.OrderDate) AS gun\n  FROM Orders o\n  WHERE o.ShippedDate IS NOT NULL\n)\nSELECT CASE WHEN gun <= 7 THEN '0-7'\n            WHEN gun <= 14 THEN '8-14'\n            WHEN gun <= 21 THEN '15-21'\n            ELSE '22+' END AS sure_grubu,\n       COUNT(*) AS gonderilen,\n       SUM(CASE WHEN o.ShippedDate > o.RequiredDate THEN 1 ELSE 0 END) AS geciken,\n       ${NW_LR} AS late_rate\nFROM s o\nGROUP BY sure_grubu\nORDER BY MIN(gun);`,
    aciklama: '<p>İlk iki grupta hiç geç gönderim yok, 22+ grubunda ise çoğu sipariş geç. Bunun sebebi veri yapısı: istenen teslim süresi sadece 14, 28 ya da 42 gün olabiliyor. 14 günden kısa sürede gönderilen bir sipariş tanım gereği geç olamaz.</p><p>Bu, <b>hedef sızıntısı</b> (target leakage) için iyi bir örnek. Sevkiyat süresi geç gönderimi neredeyse tanımlıyor, ama sipariş anında bilinmiyor. Gecikmeyi tahmin etmek isteyen bir model bu değişkeni kullanamaz. 23. sorudaki risk skoru bu yüzden sadece önceden bilinen özelliklerle kuruluyor.</p>' },
  { id: 'w16', dil: 'sql', seviye: 3, kategori: 'Aggregation', baslik: 'Ülke × taşıyıcı', sirali: true,
    soru: '<p>ShipCountry ve Shipper birlikte ele alındığında hangi kombinasyonlarda Late Shipment Rate yükseliyor?</p>' + NW_TANIM + '<p>En az 10 gönderilmiş siparişi olan kombinasyonlardan oranı en yüksek 10 tanesi. Beklenen çıktı: <code>ShipCountry</code>, <code>tasiyici</code>, <code>gonderilen</code>, <code>late_rate</code>. Oran azalan, eşitlikte ülke ve taşıyıcı adına göre.</p>',
    ipucu: 'İki sütunla GROUP BY, <code>HAVING COUNT(*) &gt;= 10</code>, tie-breaker\'lı ORDER BY, <code>LIMIT 10</code>.',
    cozum: `SELECT o.ShipCountry,\n       s.CompanyName AS tasiyici,\n       COUNT(*) AS gonderilen,\n       ${NW_LR} AS late_rate\nFROM Orders o\nJOIN Shippers s ON s.ShipperID = o.ShipVia\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY o.ShipCountry, s.CompanyName\nHAVING COUNT(*) >= 10\nORDER BY late_rate DESC, o.ShipCountry, tasiyici\nLIMIT 10;`,
    aciklama: '<p>21 ülke × 3 taşıyıcı = 63 olası kombinasyon. Çoğu birkaç siparişten oluşuyor. Eşik koymadan sıralasaydın listenin başı "1 siparişte 1 gecikme = %100" gibi anlamsız satırlarla dolardı.</p><p>Eşik 10 bile düşük: 10 siparişte 2 gecikme %20 eder. Bu tablo kesin sonuç değil, "nereye bakmalı" sorusunun cevabı. Bulunan kombinasyonları birkaç ay daha izlemek gerekir.</p>' },
  { id: 'w17', dil: 'sql', seviye: 2, kategori: 'CASE WHEN', baslik: 'Yüksek tutarlı siparişler', sirali: true,
    soru: '<p>Yüksek tutarlı siparişlerde Late Shipment Rate değerini incele.</p><p>Yüksek tutarlı = sipariş tutarı 3000 ve üzeri. Bu grubu diğerleriyle karşılaştır.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>grup</code> (<code>Yüksek tutarlı</code> / <code>Diğer</code>), <code>gonderilen</code>, <code>ort_tutar</code> (2 ondalık), <code>late_rate</code>. Önce Yüksek tutarlı.</p>',
    ipucu: 'Tutar CTE\'si + CASE ile iki grup.',
    cozum: `WITH t AS (\n  ${NW_TUTAR}\n)\nSELECT CASE WHEN t.tutar >= 3000 THEN 'Yüksek tutarlı' ELSE 'Diğer' END AS grup,\n       COUNT(*) AS gonderilen,\n       ROUND(AVG(t.tutar), 2) AS ort_tutar,\n       ${NW_LR} AS late_rate\nFROM Orders o\nJOIN t ON t.OrderID = o.OrderID\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY grup\nORDER BY grup DESC;`,
    aciklama: '<p>4. sorudaki "Çok büyük" grubunu diğer her şeyle karşılaştırıyoruz. Yüksek tutarlı siparişlerde oran yaklaşık 1,5 kat (%6,7\'ye karşı %4,3). Bu siparişler gelirin büyük kısmını oluşturduğu için, oran farkının parasal etkisi sipariş sayısından çok daha büyük.</p><p>Yönetici özetinde "geç giden siparişlerin toplam tutarı" gibi parasal bir metrik eklemek, oranı daha anlamlı kılar.</p>' },
  { id: 'w18', dil: 'sql', seviye: 3, kategori: 'CASE WHEN', baslik: 'Yüksek navlun × uzun sevkiyat', sirali: true,
    soru: '<p>Yüksek Freight ile uzun sevkiyat süresinin birlikte görüldüğü siparişleri analiz et.</p><p>Yüksek navlun = <code>Freight &gt;= 100</code>. Uzun sevkiyat = 14 günden fazla. Dört kombinasyonu karşılaştır.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>navlun</code> (<code>Yüksek</code> / <code>Normal</code>), <code>sevkiyat</code> (<code>Uzun</code> / <code>Normal</code>), <code>gonderilen</code>, <code>ort_tutar</code> (2 ondalık), <code>late_rate</code>. Önce navluna, sonra sevkiyata göre alfabetik sırala.</p>',
    ipucu: 'İki ayrı CASE ifadesiyle iki boyutlu GROUP BY.',
    cozum: `WITH t AS (\n  ${NW_TUTAR}\n)\nSELECT CASE WHEN o.Freight >= 100 THEN 'Yüksek' ELSE 'Normal' END AS navlun,\n       CASE WHEN julianday(o.ShippedDate) - julianday(o.OrderDate) > 14 THEN 'Uzun' ELSE 'Normal' END AS sevkiyat,\n       COUNT(*) AS gonderilen,\n       ROUND(AVG(t.tutar), 2) AS ort_tutar,\n       ${NW_LR} AS late_rate\nFROM Orders o\nJOIN t ON t.OrderID = o.OrderID\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY navlun, sevkiyat\nORDER BY navlun, sevkiyat;`,
    aciklama: '<p>Uzun sevkiyatlı siparişlerde oran navlundan bağımsız olarak çok yüksek (15. sorudaki sızıntı etkisi). Navlunun kendisinin geç gönderimle ilişkisi ise zayıf.</p><p>Yüksek navlunlu siparişlerin ortalama tutarı belirgin şekilde daha yüksek: navlun büyük ölçüde sipariş büyüklüğünü yansıtıyor. İki değişken arasındaki bu bağ (korelasyon), "yüksek navlun riski" gibi bir yorumun aslında "büyük sipariş riski" olabileceğini gösteriyor.</p>' },
  { id: 'w19', dil: 'sql', seviye: 3, kategori: 'Aggregation', baslik: 'Çalışan × taşıyıcı ilk 10', sirali: true,
    soru: '<p>Employee × Shipper bazında en yüksek Late Shipment Rate değerine sahip, en az 5 gönderilmiş sipariş içeren ilk 10 kombinasyonu bul.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>calisan</code> (<code>FirstName || \' \' || LastName</code>), <code>tasiyici</code>, <code>gonderilen</code>, <code>late_rate</code>. Oran azalan, eşitlikte çalışan ve taşıyıcı adına göre.</p>',
    ipucu: 'Employees → Orders → Shippers, iki sütunla GROUP BY, <code>HAVING COUNT(*) &gt;= 5</code>.',
    cozum: `SELECT e.FirstName || ' ' || e.LastName AS calisan,\n       s.CompanyName AS tasiyici,\n       COUNT(*) AS gonderilen,\n       ${NW_LR} AS late_rate\nFROM Orders o\nJOIN Employees e ON e.EmployeeID = o.EmployeeID\nJOIN Shippers s ON s.ShipperID = o.ShipVia\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY e.EmployeeID, calisan, tasiyici\nHAVING COUNT(*) >= 5\nORDER BY late_rate DESC, calisan, tasiyici\nLIMIT 10;`,
    aciklama: '<p>16. sorudaki kalıbın aynısı, farklı boyutlarla: iki boyutlu grupla, küçük grupları ele, sırala ve kes.</p><p>Çalışan bazında oranlar, siparişi alan kişinin gecikmede rolü olduğunu ima edebilir. Ama Northwind\'de çalışanlar satış temsilcisi, sevkiyatı onlar yapmıyor. Kurumsal bir rapora "X kişisinin siparişleri geç gidiyor" yazmadan önce süreçte gerçekten neyi kontrol ettiğini sormak gerekir.</p>' },

  // ───────── İleri SQL ─────────
  { id: 'w20', dil: 'sql', seviye: 3, kategori: 'Subquery / CTE', baslik: 'Tutar grupları LiftScore', sirali: true,
    soru: '<p>Sipariş tutarı grupları için LiftScore hesapla: Grup Late Shipment Rate / Genel Late Shipment Rate.</p><p>4. sorudaki tutar gruplarını kullan.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>tutar_grubu</code>, <code>late_rate</code>, <code>genel_rate</code>, <code>lift</code> (hepsi 2 ondalık). Küçükten büyüğe sırala.</p>',
    ipucu: 'Genel oranı tek satırlık bir CTE\'de hesapla, CROSS JOIN ile her gruba taşı. Lift\'i yuvarlanmamış oranlarla hesapla.',
    cozum: `WITH t AS (\n  ${NW_TUTAR}\n), g AS (\n  SELECT AVG(CASE WHEN ShippedDate > RequiredDate THEN 1.0 ELSE 0 END) AS genel\n  FROM Orders WHERE ShippedDate IS NOT NULL\n), grp AS (\n  SELECT ${NW_GRUP} AS tutar_grubu,\n         MIN(t.tutar) AS alt,\n         AVG(CASE WHEN o.ShippedDate > o.RequiredDate THEN 1.0 ELSE 0 END) AS oran\n  FROM Orders o JOIN t ON t.OrderID = o.OrderID\n  WHERE o.ShippedDate IS NOT NULL\n  GROUP BY tutar_grubu\n)\nSELECT tutar_grubu,\n       ROUND(100 * oran, 2) AS late_rate,\n       ROUND(100 * genel, 2) AS genel_rate,\n       ROUND(oran / genel, 2) AS lift\nFROM grp CROSS JOIN g\nORDER BY alt;`,
    aciklama: '<p>Lift 1\'in üzerindeyse grup ortalamadan riskli. Nadir olaylarda (burada %4,6) lift, yüzde puan farkından daha anlaşılır: "%6,7 ile %4,6 arasında 2 puan fark" yerine "ortalamanın yaklaşık 1,5 katı risk" demek yöneticiye daha net gelir.</p><p>Grup sıralaması için en küçük tutarı (<code>alt</code>) CTE içinde taşıdık. Dış sorguda artık OrderDetails\'e erişim olmadığı için <code>MIN(t.tutar)</code> orada yazılamaz.</p>' },
  { id: 'w21', dil: 'sql', seviye: 3, kategori: 'Window Functions', baslik: 'Taşıyıcıların genelden farkı', sirali: true,
    soru: '<p>Shipper bazında Late Shipment Rate değerinin genel orandan farkını hesapla.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>tasiyici</code>, <code>late_rate</code>, <code>genel_rate</code>, <code>fark</code> (yüzde puan, oran − genel; hepsi 2 ondalık). Farkı en büyük en üstte.</p>',
    ipucu: 'Genel oranı ham veriden hesapla. Taşıyıcı oranlarının ortalaması genel oran değildir.',
    cozum: `WITH ts AS (\n  SELECT s.CompanyName AS tasiyici,\n         100.0 * AVG(CASE WHEN o.ShippedDate > o.RequiredDate THEN 1 ELSE 0 END) AS oran\n  FROM Orders o JOIN Shippers s ON s.ShipperID = o.ShipVia\n  WHERE o.ShippedDate IS NOT NULL\n  GROUP BY s.CompanyName\n)\nSELECT tasiyici,\n       ROUND(oran, 2) AS late_rate,\n       ROUND(g.genel, 2) AS genel_rate,\n       ROUND(oran - g.genel, 2) AS fark\nFROM ts\nCROSS JOIN (SELECT 100.0 * AVG(CASE WHEN ShippedDate > RequiredDate THEN 1 ELSE 0 END) AS genel\n            FROM Orders WHERE ShippedDate IS NOT NULL) g\nORDER BY fark DESC;`,
    aciklama: '<p>Lift oran verir (kaç kat), fark yüzde puan verir. Taşıyıcılar arasındaki farklar ±1 puan civarında, yani pratikte hepsi genel orana çok yakın.</p><p><b>Tuzak:</b> <code>AVG(oran) OVER ()</code> ile "genel" oranı almak, üç taşıyıcı oranının basit ortalamasını verir. Taşıyıcıların sipariş sayıları farklı olduğu için bu gerçek genel orandan sapar. Genel oranı her zaman ham veriden hesapla.</p>' },
  { id: 'w22', dil: 'sql', seviye: 3, kategori: 'Subquery / CTE', baslik: 'Ülke × taşıyıcı × tutar segmenti', sirali: true,
    soru: '<p>ShipCountry × Shipper × OrderValueSegment kırılımını analiz et.</p><p>OrderValueSegment = 4. sorudaki tutar grupları. En az 5 gönderilmiş siparişi olan kombinasyonlardan oranı en yüksek 10 tanesini getir.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>ShipCountry</code>, <code>tasiyici</code>, <code>segment</code>, <code>gonderilen</code>, <code>late_rate</code>. Oran azalan, eşitlikte ülke, taşıyıcı ve segmente göre.</p>',
    ipucu: 'Tutar CTE\'si + iki JOIN + üç boyutlu GROUP BY + HAVING + LIMIT.',
    cozum: `WITH t AS (\n  ${NW_TUTAR}\n)\nSELECT o.ShipCountry,\n       s.CompanyName AS tasiyici,\n       ${NW_GRUP} AS segment,\n       COUNT(*) AS gonderilen,\n       ${NW_LR} AS late_rate\nFROM Orders o\nJOIN t ON t.OrderID = o.OrderID\nJOIN Shippers s ON s.ShipperID = o.ShipVia\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY o.ShipCountry, tasiyici, segment\nHAVING COUNT(*) >= 5\nORDER BY late_rate DESC, o.ShipCountry, tasiyici, segment\nLIMIT 10;`,
    aciklama: '<p>Üç boyut, küçük gruplar demek: 830 sipariş yüzlerce olası hücreye dağılıyor. En az 5 eşiğiyle bile listenin üst kısmındaki oranlar 1-2 gecikmeye dayanıyor.</p><p>Çok boyutlu kırılımların gerçek değeri tek tek hücrelerde değil, tekrar eden örüntülerde: listede aynı ülke ya da aynı segment birden fazla kez çıkıyorsa, o boyut muhtemelen gerçekten önemli.</p>' },
  { id: 'w23', dil: 'sql', seviye: 3, kategori: 'CASE WHEN', baslik: 'OperationalRiskScore', sirali: true,
    soru: '<p>Siparişleri, sevkiyat gerçekleşmeden önce bilinebilecek özelliklerle kural tabanlı bir OperationalRiskScore ile sırala.</p><p>Kurallar: istenen teslim süresi (<code>RequiredDate − OrderDate</code>) 14 gün <b>+2</b>; sipariş tutarı 3000 ve üzeri <b>+1</b>; sipariş 4 ya da daha fazla kalem içeriyor <b>+1</b>; Freight 100 ve üzeri <b>+1</b>.</p><p>Beklenen çıktı: en riskli 15 sipariş. <code>OrderID</code>, <code>CustomerID</code>, <code>risk_skoru</code>. Skor azalan, eşitlikte OrderID.</p>',
    ipucu: 'Sipariş başına tutar ve kalem sayısını CTE\'de hesapla, kuralları CASE\'lerle topla.',
    cozum: "WITH s AS (\n  SELECT OrderID,\n         SUM(UnitPrice * Quantity * (1 - Discount)) AS tutar,\n         COUNT(*) AS kalem\n  FROM OrderDetails\n  GROUP BY OrderID\n)\nSELECT o.OrderID, o.CustomerID,\n       (CASE WHEN julianday(o.RequiredDate) - julianday(o.OrderDate) = 14 THEN 2 ELSE 0 END)\n     + (CASE WHEN s.tutar >= 3000 THEN 1 ELSE 0 END)\n     + (CASE WHEN s.kalem >= 4 THEN 1 ELSE 0 END)\n     + (CASE WHEN o.Freight >= 100 THEN 1 ELSE 0 END) AS risk_skoru\nFROM Orders o\nJOIN s ON s.OrderID = o.OrderID\nORDER BY risk_skoru DESC, o.OrderID\nLIMIT 15;",
    aciklama: '<p>Anahtar kısıt "sevkiyattan önce bilinebilecek": sevkiyat süresi ya da gönderim tarihi gibi sonradan oluşan bilgiler kullanılamaz (15. sorudaki sızıntı). Sipariş anında bilinenler: istenen teslim süresi, tutar, kalem sayısı, navlun, taşıyıcı, ülke.</p><p>En güçlü sinyal kısa teslim süresi: 14 günlük siparişlerde geç gönderim oranı genelin yaklaşık dört katı. Bu yüzden ona +2 verdik. Skorun işe yarayıp yaramadığını 24. soru ölçüyor.</p>' },
  { id: 'w24', dil: 'sql', seviye: 3, kategori: 'CASE WHEN', baslik: 'Risk skoruna göre gerçek oran', sirali: true,
    soru: '<p>OperationalRiskScore seviyelerine göre gerçek Late Shipment Rate değerini ölç.</p><p>23. sorudaki kuralları kullan.</p>' + NW_TANIM + '<p>Beklenen çıktı: <code>risk_skoru</code>, <code>gonderilen</code>, <code>geciken</code>, <code>late_rate</code>. Skora göre sırala.</p>',
    ipucu: '23. sorudaki skoru bir CTE\'ye al, sonra skora göre grupla.',
    cozum: `WITH s AS (\n  SELECT OrderID,\n         SUM(UnitPrice * Quantity * (1 - Discount)) AS tutar,\n         COUNT(*) AS kalem\n  FROM OrderDetails\n  GROUP BY OrderID\n), r AS (\n  SELECT o.*,\n         (CASE WHEN julianday(o.RequiredDate) - julianday(o.OrderDate) = 14 THEN 2 ELSE 0 END)\n       + (CASE WHEN s.tutar >= 3000 THEN 1 ELSE 0 END)\n       + (CASE WHEN s.kalem >= 4 THEN 1 ELSE 0 END)\n       + (CASE WHEN o.Freight >= 100 THEN 1 ELSE 0 END) AS risk_skoru\n  FROM Orders o JOIN s ON s.OrderID = o.OrderID\n)\nSELECT risk_skoru,\n       COUNT(*) AS gonderilen,\n       SUM(CASE WHEN o.ShippedDate > o.RequiredDate THEN 1 ELSE 0 END) AS geciken,\n       ${NW_LR} AS late_rate\nFROM r o\nWHERE o.ShippedDate IS NOT NULL\nGROUP BY risk_skoru\nORDER BY risk_skoru;`,
    aciklama: '<p>Bir skorun değerini ölçmenin yolu bu tablo: skor arttıkça gerçek oran artıyor mu? Burada <b>düzgün artmıyor</b>. Skor 2\'de oran %10\'a çıkıyor, ama 3 ve 4\'te düşüyor. Skor 5\'teki %50 ise sadece 6 siparişe dayanıyor.</p><p>Yorum: skorun gerçekten işe yarayan tek parçası kısa teslim süresi (+2). Tutar, kalem sayısı ve navlun kuralları geç gönderimi belirgin şekilde ayırt etmiyor. Bu kuralları atıp sadece "14 günlük sipariş mi?" diye sormak muhtemelen aynı işi görür.</p><p>Bu, ödevin belki de en değerli dersi: bir skoru kurmak yetmez, gerçek sonuçla doğrulamak gerekir. Kural tabanlı skorlar makine öğrenmesi modeli kurmadan önce iyi bir başlangıç noktası ve modelin geçmesi gereken bir "baz çizgi" (baseline) sağlar. Ama ancak doğrulandıktan sonra.</p>' },

  // ───────── SorguLab ek soruları ─────────
  { id: 'w25', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'Çalışan ve yöneticisi (self-join)', sirali: true,
    soru: '<p>Her çalışanın adını, unvanını ve bağlı olduğu yöneticinin adını getir. Yöneticisi olmayan çalışan da listede olsun (yönetici boş). Beklenen çıktı: <code>calisan</code>, <code>Title</code>, <code>yonetici</code> (ikisi de <code>FirstName || \' \' || LastName</code>). EmployeeID\'ye göre sırala.</p>',
    ipucu: 'Employees tablosunu kendisiyle birleştir: <code>Employees e LEFT JOIN Employees m ON m.EmployeeID = e.ReportsTo</code>.',
    cozum: "SELECT e.FirstName || ' ' || e.LastName AS calisan,\n       e.Title,\n       m.FirstName || ' ' || m.LastName AS yonetici\nFROM Employees e\nLEFT JOIN Employees m ON m.EmployeeID = e.ReportsTo\nORDER BY e.EmployeeID;",
    aciklama: '<p><b>Self-join</b>: bir tabloyu kendisiyle birleştirmek. Aynı tabloya iki farklı takma ad (<code>e</code> çalışan, <code>m</code> yönetici) vererek iki ayrı tablo gibi kullanıyoruz. <code>ReportsTo</code> sütunu, aynı tablodaki başka bir satırın EmployeeID\'sini gösteriyor.</p><p>INNER JOIN kullansaydın, kimseye bağlı olmayan Andrew Fuller (Vice President) listeden düşerdi. Hiyerarşilerde tepedeki kişiyi kaybetmemek için LEFT JOIN gerekir.</p>' },
  { id: 'w26', dil: 'sql', seviye: 3, kategori: 'Subquery / CTE', baslik: 'Organizasyon şeması (recursive CTE)', sirali: true,
    soru: '<p>Organizasyon hiyerarşisini en tepeden başlayarak çıkar. Her çalışan için hiyerarşideki seviyesini (en tepe 1) ve tepeden kendisine kadar olan yolu göster. Beklenen çıktı: <code>calisan</code> (<code>LastName</code>), <code>seviye</code>, <code>yol</code> (örn. <code>Fuller &gt; Buchanan &gt; Suyama</code>). Seviyeye, sonra yola göre sırala.</p>',
    ipucu: '<code>WITH RECURSIVE</code>: başlangıç satırı <code>ReportsTo IS NULL</code>, özyinelemeli kısım çalışanları bir üst seviyedeki satırla birleştirir.',
    cozum: "WITH RECURSIVE agac AS (\n  SELECT EmployeeID, LastName, 1 AS seviye, LastName AS yol\n  FROM Employees\n  WHERE ReportsTo IS NULL\n  UNION ALL\n  SELECT e.EmployeeID, e.LastName, a.seviye + 1, a.yol || ' > ' || e.LastName\n  FROM Employees e\n  JOIN agac a ON e.ReportsTo = a.EmployeeID\n)\nSELECT LastName AS calisan, seviye, yol\nFROM agac\nORDER BY seviye, yol;",
    aciklama: '<p><b>Recursive CTE</b> iki parçadan oluşur: başlangıç (anchor) sorgusu ve kendi sonucuna referans veren özyinelemeli sorgu. Her turda bir alt seviye eklenir, yeni satır gelmeyince durur.</p><p>Self-join (25. soru) sadece bir üst seviyeyi gösterir. Hiyerarşi kaç seviye derin olursa olsun tamamını gezmek için recursive CTE gerekir. Organizasyon şemaları, ürün kategori ağaçları ve malzeme listeleri (BOM) tipik kullanım alanları.</p><p><b>SQL Server notu:</b> <code>RECURSIVE</code> kelimesi yazılmaz, sadece <code>WITH agac AS (...)</code>. Metin birleştirmede de <code>+</code> kullanılır ve tiplerin uyması için <code>CAST(... AS NVARCHAR(200))</code> gerekebilir.</p>' },
  { id: 'w27', dil: 'sql', seviye: 1, kategori: 'Filtreleme', baslik: 'Yeniden sipariş verilmesi gereken ürünler',
    soru: '<p>Satışı devam eden (<code>Discontinued = 0</code>) ve stoktaki artı yoldaki miktarı (<code>UnitsInStock + UnitsOnOrder</code>) yeniden sipariş seviyesinin (<code>ReorderLevel</code>) altında ya da ona eşit olan ürünleri bul. Beklenen çıktı: <code>ProductName</code>, <code>UnitsInStock</code>, <code>UnitsOnOrder</code>, <code>ReorderLevel</code>.</p>',
    ipucu: 'WHERE içinde iki sütunun toplamını üçüncüyle karşılaştırabilirsin.',
    cozum: "SELECT ProductName, UnitsInStock, UnitsOnOrder, ReorderLevel\nFROM Products\nWHERE Discontinued = 0\n  AND UnitsInStock + UnitsOnOrder <= ReorderLevel;",
    aciklama: '<p>Klasik stok yönetimi sorusu. Yoldaki miktarı (UnitsOnOrder) hesaba katmazsan, tedarikçiye zaten sipariş verilmiş ürünler için tekrar sipariş önerirsin.</p><p>Satışı durdurulmuş ürünleri dışarıda tutmak da kritik. Discontinued bir ürün için stok uyarısı anlamsız. Bu tip "iş kuralı filtreleri" bir raporun güvenilirliğini belirler.</p>' },
  { id: 'w28', dil: 'sql', seviye: 2, kategori: 'Aggregation', baslik: 'Tedarikçi ülkeleri', sirali: true,
    soru: '<p>Tedarikçilerin bulunduğu ülkelere göre tedarikçi sayısını, ürün sayısını ve bu ürünlerin kaç farklı kategoride olduğunu bul. Beklenen çıktı: <code>Country</code>, <code>tedarikci</code>, <code>urun</code>, <code>kategori</code>. Ürün sayısına göre azalan, eşitlikte ülke adı.</p>',
    ipucu: 'Suppliers LEFT JOIN Products; tedarikçi ve kategori için <code>COUNT(DISTINCT ...)</code>.',
    cozum: "SELECT s.Country,\n       COUNT(DISTINCT s.SupplierID) AS tedarikci,\n       COUNT(p.ProductID) AS urun,\n       COUNT(DISTINCT p.CategoryID) AS kategori\nFROM Suppliers s\nLEFT JOIN Products p ON p.SupplierID = s.SupplierID\nGROUP BY s.Country\nORDER BY urun DESC, s.Country;",
    aciklama: '<p>Tek sorguda üç farklı sayım ve hepsinin seviyesi farklı. JOIN sonrası her satır bir ürün olduğu için tedarikçi sayısında <code>DISTINCT</code> şart, yoksa her tedarikçi ürün sayısı kadar sayılır.</p><p>Tedarik zinciri riski açısından bakılabilecek bir tablo: tek bir ülkeye çok bağımlı kategoriler var mı?</p>' },
  { id: 'w29', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'Hiç sipariş vermemiş müşteriler',
    soru: '<p>Hiç siparişi olmayan müşterileri bul. Beklenen çıktı: <code>CustomerID</code>, <code>CompanyName</code>, <code>Country</code>.</p>',
    ipucu: 'LEFT JOIN + <code>IS NULL</code> ya da <code>NOT EXISTS</code>.',
    cozum: "SELECT c.CustomerID, c.CompanyName, c.Country\nFROM Customers c\nWHERE NOT EXISTS (SELECT 1 FROM Orders o WHERE o.CustomerID = c.CustomerID);",
    aciklama: '<p>Anti-join kalıbının <code>NOT EXISTS</code> ile yazımı. Alt sorgu her müşteri için "bu müşterinin en az bir siparişi var mı?" diye sorar, olmayanları getirir.</p><p><code>NOT IN</code> de çalışır, ama alt sorgunun döndürdüğü sütunda tek bir NULL bile varsa hiç satır döndürmez. Orders.CustomerID NULL olabilen bir sütun olduğu için burada <code>NOT EXISTS</code> daha güvenli seçim.</p>' },
  { id: 'w30', dil: 'sql', seviye: 3, kategori: 'Window Functions', baslik: 'Her ülkenin en büyük müşterisi', sirali: true,
    soru: '<p>Her ülkede toplam satışı en yüksek müşteriyi ve bu müşterinin ülke satışlarındaki payını bul. Beklenen çıktı: <code>Country</code>, <code>CompanyName</code>, <code>satis</code> (2 ondalık), <code>ulke_payi</code> (%, 2 ondalık). Ülke adına göre sırala.</p>',
    ipucu: 'Müşteri bazında satışı topla. <code>SUM(satis) OVER (PARTITION BY Country)</code> ülke toplamını, <code>ROW_NUMBER()</code> sıralamayı verir.',
    cozum: "WITH m AS (\n  SELECT c.Country, c.CompanyName,\n         SUM(od.UnitPrice * od.Quantity * (1 - od.Discount)) AS satis\n  FROM Customers c\n  JOIN Orders o ON o.CustomerID = c.CustomerID\n  JOIN OrderDetails od ON od.OrderID = o.OrderID\n  GROUP BY c.CustomerID, c.Country, c.CompanyName\n), s AS (\n  SELECT *,\n         100.0 * satis / SUM(satis) OVER (PARTITION BY Country) AS pay,\n         ROW_NUMBER() OVER (PARTITION BY Country ORDER BY satis DESC) AS rn\n  FROM m\n)\nSELECT Country, CompanyName, ROUND(satis, 2) AS satis, ROUND(pay, 2) AS ulke_payi\nFROM s\nWHERE rn = 1\nORDER BY Country;",
    aciklama: '<p>İki window fonksiyonu aynı anda: biri payın paydasını (ülke toplamı), diğeri ülke içi sıralamayı veriyor. İkisi de aynı <code>PARTITION BY Country</code> çerçevesini kullanıyor.</p><p>Bazı ülkelerde en büyük müşteri satışların yarısından fazlasını oluşturuyor, tek müşterili ülkelerde ise pay %100. Müşteri yoğunlaşması (concentration) riski böyle ölçülür: tek müşteriye bağlı bir pazar, o müşteri kaybedildiğinde tamamen gider.</p>' },
  { id: 'w31', dil: 'sql', seviye: 2, kategori: 'Subquery / CTE', baslik: 'Kategori ortalamasından pahalı ürünler', sirali: true,
    soru: '<p>Liste fiyatı (<code>Products.UnitPrice</code>) kendi kategorisinin ortalama fiyatından yüksek olan ürünleri bul. Beklenen çıktı: <code>CategoryName</code>, <code>ProductName</code>, <code>UnitPrice</code>, <code>kategori_ort</code> (2 ondalık). Kategori adına, sonra fiyata göre azalan sırala.</p>',
    ipucu: 'Korelasyonlu alt sorgu: <code>WHERE p.UnitPrice &gt; (SELECT AVG(UnitPrice) FROM Products WHERE CategoryID = p.CategoryID)</code>. Ya da window AVG.',
    cozum: "WITH k AS (\n  SELECT p.*, AVG(p.UnitPrice) OVER (PARTITION BY p.CategoryID) AS kategori_ort\n  FROM Products p\n)\nSELECT c.CategoryName, k.ProductName, k.UnitPrice, ROUND(k.kategori_ort, 2) AS kategori_ort\nFROM k\nJOIN Categories c ON c.CategoryID = k.CategoryID\nWHERE k.UnitPrice > k.kategori_ort\nORDER BY c.CategoryName, k.UnitPrice DESC;",
    aciklama: '<p>İki yolu var ve ikisi de aynı sonucu verir:</p><ul><li><b>Korelasyonlu alt sorgu</b>: her ürün için kendi kategorisinin ortalamasını ayrı ayrı hesaplar. Okunması kolay ama büyük tablolarda yavaş olabilir.</li><li><b>Window fonksiyonu</b>: tüm ortalamaları tek geçişte hesaplar ve her satıra ekler.</li></ul><p>Window yolu ortalamayı çıktıda göstermeyi de kolaylaştırıyor.</p>' },
  { id: 'w32', dil: 'sql', seviye: 2, kategori: 'JOIN', baslik: 'Çalışanların bölgeleri', sirali: true,
    soru: '<p>Her çalışanın sorumlu olduğu bölge (Region) adını ve o bölgede kaç bölgeye (Territory) baktığını bul. Beklenen çıktı: <code>calisan</code> (<code>FirstName || \' \' || LastName</code>), <code>bolge</code> (RegionDescription), <code>territory_sayisi</code>. Çalışan adına göre sırala.</p>',
    ipucu: 'Employees → EmployeeTerritories → Territories → Region. Dört tablo, ara tablo üzerinden çoka-çok ilişki.',
    cozum: "SELECT e.FirstName || ' ' || e.LastName AS calisan,\n       r.RegionDescription AS bolge,\n       COUNT(*) AS territory_sayisi\nFROM Employees e\nJOIN EmployeeTerritories et ON et.EmployeeID = e.EmployeeID\nJOIN Territories t ON t.TerritoryID = et.TerritoryID\nJOIN Region r ON r.RegionID = t.RegionID\nGROUP BY e.EmployeeID, calisan, bolge\nORDER BY calisan;",
    aciklama: '<p><code>EmployeeTerritories</code> bir <b>ara tablo</b> (junction / bridge table): bir çalışan birden fazla bölgeye, bir bölge birden fazla çalışana bağlanabiliyor. Çoka-çok (many-to-many) ilişkiler veritabanlarında hep böyle kurulur.</p><p>Veride her çalışan tek bir bölgeye bakıyor, ama bunu varsaymak yerine GROUP BY\'a bölgeyi de koyduk. Bir çalışan iki bölgeye baksaydı iki satırda görünürdü.</p><p>RegionDescription değerleri SQL Server\'da <code>nchar</code> olduğu için sağdan boşlukla doldurulur. Bu veride boşluklar kırpıldı, SQL Server\'da karşılaştırma yaparken <code>RTRIM</code> gerekebilir.</p>' },
  { id: 'w33', dil: 'sql', seviye: 3, kategori: 'Subquery / CTE', baslik: '1998\'de geri gelmeyen müşteriler', sirali: true,
    soru: '<p>1997\'de sipariş verip 1998\'de hiç sipariş vermeyen müşterileri bul. Beklenen çıktı: <code>CustomerID</code>, <code>CompanyName</code>, <code>siparis_1997</code>. 1997 sipariş sayısına göre azalan, eşitlikte CustomerID.</p>',
    ipucu: '1997 siparişlerini grupla, <code>NOT EXISTS</code> ile 1998 siparişi olanları ele. Ya da <code>EXCEPT</code>.',
    cozum: "SELECT c.CustomerID, c.CompanyName, COUNT(*) AS siparis_1997\nFROM Customers c\nJOIN Orders o ON o.CustomerID = c.CustomerID\nWHERE strftime('%Y', o.OrderDate) = '1997'\n  AND NOT EXISTS (\n    SELECT 1 FROM Orders o2\n    WHERE o2.CustomerID = c.CustomerID\n      AND strftime('%Y', o2.OrderDate) = '1998'\n  )\nGROUP BY c.CustomerID, c.CompanyName\nORDER BY siparis_1997 DESC, c.CustomerID;",
    aciklama: '<p>Basit bir churn (müşteri kaybı) tanımı: bir dönemde aktif olup sonraki dönemde hiç gelmeyenler. Yönetici diliyle "geri kazanılması gereken müşteri listesi".</p><p>Dikkat: 1998 verisi Mayıs\'ta bitiyor, yani 1998 yarım bir yıl. Bu listedeki bazı müşteriler yılın geri kalanında gelebilirdi. Churn analizinde gözlem penceresinin eşit uzunlukta olması önemli. Daha adil bir karşılaştırma 1997\'nin ilk 5 ayı ile 1998\'in ilk 5 ayı olurdu.</p><p>Alternatif yazım: <code>SELECT CustomerID FROM ... 1997 EXCEPT SELECT CustomerID FROM ... 1998</code>.</p>' },
  { id: 'w34', dil: 'sql', seviye: 3, kategori: 'JOIN', baslik: 'Birlikte alınan ürünler', sirali: true,
    soru: '<p>Aynı siparişte en sık birlikte alınan 5 ürün çiftini bul. Her çift bir kez sayılsın (A-B ile B-A aynı). Beklenen çıktı: <code>urun_1</code>, <code>urun_2</code> (ürün adları, ProductID\'si küçük olan önce), <code>birlikte</code> (ortak sipariş sayısı). Sayıya göre azalan, eşitlikte urun_1 ve urun_2 adına göre.</p>',
    ipucu: 'OrderDetails\'i kendisiyle aynı OrderID üzerinden birleştir, <code>a.ProductID &lt; b.ProductID</code> koşuluyla tekrarları ele.',
    cozum: "SELECT p1.ProductName AS urun_1,\n       p2.ProductName AS urun_2,\n       COUNT(*) AS birlikte\nFROM OrderDetails a\nJOIN OrderDetails b ON b.OrderID = a.OrderID AND a.ProductID < b.ProductID\nJOIN Products p1 ON p1.ProductID = a.ProductID\nJOIN Products p2 ON p2.ProductID = b.ProductID\nGROUP BY a.ProductID, b.ProductID\nORDER BY birlikte DESC, urun_1, urun_2\nLIMIT 5;",
    aciklama: '<p><b>Sepet analizi</b> (market basket) için temel sorgu. OrderDetails\'i kendisiyle aynı sipariş üzerinden birleştirince her sipariş içindeki tüm ürün çiftleri çıkar.</p><p><code>a.ProductID &lt; b.ProductID</code> koşulu iki işi birden yapıyor: bir ürünün kendisiyle eşleşmesini (A-A) ve aynı çiftin iki kez sayılmasını (A-B, B-A) önlüyor. <code>&lt;&gt;</code> kullansaydın her çift iki kez gelirdi.</p><p>Bir sonraki adım "lift" hesabı olur: birlikte alınma, iki ürünün ayrı ayrı popülerliğinden beklenenden ne kadar fazla?</p>' },
  { id: 'w35', dil: 'sql', seviye: 3, kategori: 'Window Functions', baslik: '1997 aylık satış ve kümülatif', sirali: true,
    soru: '<p>1997 yılında aylık satış tutarını, yılbaşından itibaren kümülatif satışı ve bir önceki aya göre değişimi (%) bul. Beklenen çıktı: <code>ay</code> (YYYY-MM), <code>satis</code>, <code>kumulatif</code>, <code>degisim_yuzde</code> (hepsi 2 ondalık; ocak için değişim boş). Aya göre sırala.</p>',
    ipucu: 'Aylık toplamı CTE\'de hesapla. <code>SUM(...) OVER (ORDER BY ay)</code> kümülatif, <code>LAG(...)</code> önceki ay.',
    cozum: "WITH a AS (\n  SELECT strftime('%Y-%m', o.OrderDate) AS ay,\n         SUM(od.UnitPrice * od.Quantity * (1 - od.Discount)) AS satis\n  FROM Orders o\n  JOIN OrderDetails od ON od.OrderID = o.OrderID\n  WHERE o.OrderDate >= '1997-01-01' AND o.OrderDate < '1998-01-01'\n  GROUP BY ay\n)\nSELECT ay,\n       ROUND(satis, 2) AS satis,\n       ROUND(SUM(satis) OVER (ORDER BY ay), 2) AS kumulatif,\n       ROUND(100.0 * (satis - LAG(satis) OVER (ORDER BY ay)) / LAG(satis) OVER (ORDER BY ay), 2) AS degisim_yuzde\nFROM a\nORDER BY ay;",
    aciklama: '<p>Zaman serisi raporlarının üç temel metriği tek sorguda: dönem değeri, kümülatif toplam ve dönemden döneme değişim.</p><p>1997, verideki tek tam yıl. Bu yüzden yıl içi trend analizi için doğru seçim. Aylık değişimler oldukça oynak: Kasım\'da %35 düşüşün ardından Aralık\'ta %64 artış var. Birkaç büyük sipariş bir ayın sonucunu belirleyebiliyor. Yöneticiye sunarken 3 aylık hareketli ortalama (<code>AVG(...) OVER (ORDER BY ay ROWS 2 PRECEDING)</code>) daha sakin bir trend gösterir.</p>' },
  // ───────── pandas ─────────
  { id: 'w36', dil: 'python', seviye: 2, kategori: 'Birleştirme', baslik: 'Taşıyıcı bazında geç gönderim (pandas)', sirali: true,
    soru: '<p>pandas ile taşıyıcı bazında gönderilmiş sipariş sayısını ve Late Shipment Rate\'i (%, 2 ondalık) hesapla. Gönderilmemiş siparişler hesaba girmesin. Sonuç: <code>CompanyName</code>, <code>gonderilen</code>, <code>late_rate</code> sütunlu, oranı en yüksek en üstte bir DataFrame. <code>sonuc</code>\'a ata.</p>',
    ipucu: '<code>dropna(subset=["ShippedDate"])</code>, sonra <code>merge</code> ile Shippers (<code>left_on="ShipVia", right_on="ShipperID"</code>).',
    cozum: 'g = Orders.dropna(subset=["ShippedDate"]).copy()\ng["gec"] = (g["ShippedDate"] > g["RequiredDate"]).astype(int)\ng = g.merge(Shippers, left_on="ShipVia", right_on="ShipperID")\nsonuc = (g.groupby("CompanyName")\n          .agg(gonderilen=("OrderID", "size"), late_rate=("gec", "mean"))\n          .reset_index())\nsonuc["late_rate"] = (sonuc["late_rate"] * 100).round(2)\nsonuc = sonuc.sort_values("late_rate", ascending=False)',
    aciklama: '<p>SQL\'deki 14. sorunun pandas karşılığı. Farklı isimli anahtarlarla birleştirmek için <code>left_on</code> / <code>right_on</code> kullanılır, SQL\'deki <code>ON o.ShipVia = s.ShipperID</code> gibi.</p><p>Tarih sütunları datetime tipinde olduğu için <code>&gt;</code> karşılaştırması doğrudan çalışıyor. NaT (eksik tarih) içeren karşılaştırmalar False döner, bu yüzden gönderilmemişleri önce <code>dropna</code> ile atmak şart. Aksi halde "geç değil" sayılıp oranı düşürürlerdi.</p><p><code>.copy()</code>: süzülmüş bir DataFrame\'e yeni sütun eklerken SettingWithCopyWarning almamak için.</p>' },
  { id: 'w37', dil: 'python', seviye: 2, kategori: 'Tarih', baslik: 'Aylık sipariş sayısı (pandas)', sirali: true,
    soru: '<p>Her ay kaç sipariş verildiğini hesapla. Ay "YYYY-MM" formatında olsun, kronolojik sırada. Sonucu <code>sonuc</code>\'a ata.</p>',
    ipucu: '<code>Orders["OrderDate"].dt.to_period("M")</code> ile grupla, <code>size()</code>, sonra index\'i metne çevir.',
    cozum: 'ay = Orders["OrderDate"].dt.to_period("M").astype(str)\nsonuc = Orders.groupby(ay).size()',
    aciklama: '<p><code>to_period("M")</code> tarihi ay dönemine çevirir. Grupladıktan sonra sonuç zaten kronolojik sıralı gelir. "YYYY-MM" metnine çevirmek de alfabetik sırayı kronolojik sıraya eşitler.</p><p>Alternatif: <code>Orders.set_index("OrderDate").resample("MS").size()</code>. resample, içinde hiç sipariş olmayan ayları da 0 olarak gösterir. groupby ise sadece verisi olan ayları gösterir. Zaman serisi grafiklerinde bu fark önemli.</p>' },
  { id: 'w38', dil: 'python', seviye: 3, kategori: 'Dönüşüm', baslik: 'Kategori × yıl satış pivotu', sirali: true,
    soru: '<p>Satırlarda kategori adı, sütunlarda sipariş yılı, hücrelerde satış tutarı (<code>UnitPrice * Quantity * (1 - Discount)</code>, 2 ondalık) olan bir pivot tablo oluştur. <code>sonuc</code>\'a ata.</p>',
    ipucu: 'OrderDetails → Orders (OrderDate), Products, Categories ile <code>merge</code> zinciri. Sonra <code>pivot_table</code>.',
    cozum: 'df = (OrderDetails\n      .merge(Orders[["OrderID", "OrderDate"]], on="OrderID")\n      .merge(Products[["ProductID", "CategoryID"]], on="ProductID")\n      .merge(Categories[["CategoryID", "CategoryName"]], on="CategoryID"))\ndf["satis"] = df["UnitPrice"] * df["Quantity"] * (1 - df["Discount"])\ndf["yil"] = df["OrderDate"].dt.year\nsonuc = pd.pivot_table(df, index="CategoryName", columns="yil",\n                       values="satis", aggfunc="sum").round(2)',
    aciklama: '<p>Dört tabloyu merge zinciriyle birleştirip pivotluyoruz. Her merge\'de sadece gereken sütunları almak hem belleği korur hem de aynı isimli sütunların çakışmasını önler. Products ile OrderDetails\'in ikisinde de <code>UnitPrice</code> var. Products\'tan da alsaydın <code>UnitPrice_x</code>, <code>UnitPrice_y</code> diye iki sütun oluşurdu.</p><p>Tabloyu okurken 1998\'in yarım bir yıl olduğunu unutma. Bir kategorinin 1998 sütunu düşük görünüyorsa bu düşüş değil, eksik veri olabilir.</p>' },
  { id: 'w39', dil: 'python', seviye: 3, kategori: 'Gruplama', baslik: 'Her kategorinin en çok satan ürünü (pandas)', sirali: true,
    soru: '<p>Her kategoride toplam satışı en yüksek ürünü bul. Sonuç: <code>CategoryName</code>, <code>ProductName</code>, <code>satis</code> (2 ondalık) sütunları, kategori adına göre sıralı bir DataFrame. <code>sonuc</code>\'a ata.</p>',
    ipucu: 'Ürün bazında satışı topla, kategori adıyla birleştir, <code>sort_values</code> + <code>groupby(...).head(1)</code>.',
    cozum: 'od = OrderDetails.assign(satis=OrderDetails["UnitPrice"] * OrderDetails["Quantity"] * (1 - OrderDetails["Discount"]))\nurun = od.groupby("ProductID", as_index=False)["satis"].sum()\nurun = (urun.merge(Products[["ProductID", "ProductName", "CategoryID"]], on="ProductID")\n            .merge(Categories[["CategoryID", "CategoryName"]], on="CategoryID"))\nsonuc = (urun.sort_values(["CategoryName", "satis"], ascending=[True, False])\n             .groupby("CategoryName").head(1)[["CategoryName", "ProductName", "satis"]]\n             .round({"satis": 2}))',
    aciklama: '<p><code>assign</code>, orijinal DataFrame\'i değiştirmeden yeni sütunlu bir kopya üretir. Bu, metot zincirlerinde temiz bir yazım sağlıyor.</p><p>"Her grubun en iyisi" kalıbı: önce grup içinde istenen sıraya diz, sonra <code>groupby(...).head(1)</code> ile her gruptan ilk satırı al. SQL\'deki <code>ROW_NUMBER() OVER (PARTITION BY ...) = 1</code> karşılığı.</p>' },
  { id: 'w40', dil: 'python', seviye: 2, kategori: 'Tarih', baslik: 'Taşıyıcı bazında sevkiyat süresi (pandas)', sirali: true,
    soru: '<p>Gönderilmiş siparişler için sevkiyat süresini (gün) hesapla. Taşıyıcı bazında ortalama, medyan ve en uzun sevkiyat süresini bul. Sonuç: <code>CompanyName</code>, <code>ortalama</code> (2 ondalık), <code>medyan</code>, <code>en_uzun</code> sütunları, taşıyıcı adına göre sıralı. <code>sonuc</code>\'a ata.</p>',
    ipucu: '<code>(ShippedDate - OrderDate).dt.days</code> gün sayısını verir.',
    cozum: 'g = Orders.dropna(subset=["ShippedDate"]).merge(Shippers, left_on="ShipVia", right_on="ShipperID")\ng["gun"] = (g["ShippedDate"] - g["OrderDate"]).dt.days\nsonuc = g.groupby("CompanyName")["gun"].agg(ortalama="mean", medyan="median", en_uzun="max").round({"ortalama": 2}).reset_index()',
    aciklama: '<p>İki datetime\'ın farkı bir Timedelta serisi verir, <code>.dt.days</code> gün sayısını çıkarır.</p><p>Ortalama ile medyanı birlikte göstermek dağılımın şeklini anlatır. Üç taşıyıcıda da ortalama medyandan yüksek: birkaç çok uzun sevkiyat ortalamayı yukarı çekiyor (sağa çarpık dağılım). Geç gönderimler de tam olarak bu uzun kuyrukta.</p>' },
  // ───────── PYTHON (pandas) · ek sorular ─────────
  {"id": "w41", "dil": "python", "seviye": 1, "kategori": "Filtreleme", "baslik": "Satıştan kalkan ürünler", "soru": "Satıştan kaldırılmış ürünleri (<code>Discontinued</code> = 1) <code>ProductName</code>, <code>UnitPrice</code>, <code>UnitsInStock</code> sütunlarıyla, fiyatı yüksek olan en üstte olacak şekilde <code>sonuc</code>'a ata.", "ipucu": "Koşulla filtrele ve sütun seç: <code>Products.loc[koşul, [sütunlar]]</code>, sonra <code>sort_values</code>.", "cozum": "sonuc = Products.loc[Products[\"Discontinued\"] == 1, [\"ProductName\", \"UnitPrice\", \"UnitsInStock\"]].sort_values(\"UnitPrice\", ascending=False)", "aciklama": "<p><code>loc[satır_koşulu, sütun_listesi]</code> filtreleme ve sütun seçimini tek adımda yapar. SQL'deki <code>SELECT ... WHERE ... ORDER BY</code> kalıbının pandas karşılığı.</p><p>8 ürün satıştan kalkmış. Yarısının stoğu 0, ama Mishi Kobe Niku, Rössle Sauerkraut gibi bazılarının hâlâ stoğu var: satıştan kaldırılan ürünün elde kalan stoğu bir iş sorusu olabilir (indirimle eritmek gibi).</p>", "sirali": true},
  {"id": "w42", "dil": "python", "seviye": 1, "kategori": "Filtreleme", "baslik": "Almanya'ya yüksek navlunlu gönderimler", "soru": "Almanya'ya gönderilen (<code>ShipCountry</code> = Germany) ve navlun ücreti (<code>Freight</code>) 200'den yüksek siparişlerin <code>OrderID</code>, <code>ShipCity</code>, <code>Freight</code> bilgilerini navlun ücretine göre azalan (eşitlikte OrderID) sırada <code>sonuc</code>'a ata.", "ipucu": "İki koşul: <code>&amp;</code> ve her koşul parantez içinde.", "cozum": "sonuc = Orders.loc[(Orders[\"ShipCountry\"] == \"Germany\") & (Orders[\"Freight\"] > 200), [\"OrderID\", \"ShipCity\", \"Freight\"]].sort_values([\"Freight\", \"OrderID\"], ascending=[False, True])", "aciklama": "<p>pandas'ta koşulları <code>and</code> ile değil <code>&amp;</code> ile birleştiririz ve her koşul parantez içinde olmalı: <code>(A == x) &amp; (B &gt; y)</code>.</p><p>15 siparişin 11'si Cunewalde'ye gidiyor. Orası Northwind'in en büyük müşterilerinden QUICK-Stop'un şehri: yüksek navlun büyük ve ağır siparişlerden geliyor. Bir filtrenin sonucuna bakarken \"bu satırlar neden bir araya geldi?\" diye sormak çoğu zaman yeni bir içgörü verir.</p>", "sirali": true},
  {"id": "w43", "dil": "python", "seviye": 1, "kategori": "Gruplama", "baslik": "Ülkelere göre müşteri sayısı", "soru": "Her ülkede kaç müşteri olduğunu say. En çok müşterisi olan 10 ülkeyi <code>Country</code> ve <code>musteri</code> sütunlarıyla, müşteri sayısına göre azalan (eşitlikte ülke adına göre) sırada <code>sonuc</code>'a ata.", "ipucu": "<code>value_counts()</code> sonucunu <code>reset_index</code> ile tabloya çevir, sonra iki kriterle sırala.", "cozum": "say = Customers[\"Country\"].value_counts().rename_axis(\"Country\").reset_index(name=\"musteri\")\nsonuc = say.sort_values([\"musteri\", \"Country\"], ascending=[False, True]).head(10)", "aciklama": "<p><code>value_counts()</code> çoktan aza sıralar, ama eşit sayıdaki değerlerin sırası garanti değildir. Burada Fransa ve Almanya 11'er müşteriyle eşit; ilk 10'u alırken sıranın her seferinde aynı olması için ikinci bir kriter (ülke adı) ekledik.</p><p><code>rename_axis(\"Country\").reset_index(name=\"musteri\")</code>: index'e ad verip normal sütuna çevirir, sayı sütununa da istediğimiz adı verir. pandas sürümleri arasında <code>value_counts</code> sonucunun sütun adları değiştiği için adları açıkça vermek kodu sağlam yapar.</p>", "sirali": true},
  {"id": "w44", "dil": "python", "seviye": 2, "kategori": "Birleştirme", "baslik": "Ülkelere göre ciro", "soru": "Her sipariş kaleminin tutarını hesapla (<code>UnitPrice × Quantity × (1 − Discount)</code>), siparişleri müşterilere bağla ve müşteri ülkesine göre toplam ciroyu bul. En yüksek ciroya sahip 5 ülkeyi <code>Country</code> ve <code>tutar</code> (2 ondalık) sütunlarıyla <code>sonuc</code>'a ata.", "ipucu": "OrderDetails → Orders (OrderID) → Customers (CustomerID). Her merge'de sadece gereken sütunları al.", "cozum": "od = OrderDetails.assign(tutar=OrderDetails[\"UnitPrice\"] * OrderDetails[\"Quantity\"] * (1 - OrderDetails[\"Discount\"]))\nd = od.merge(Orders[[\"OrderID\", \"CustomerID\"]], on=\"OrderID\").merge(Customers[[\"CustomerID\", \"Country\"]], on=\"CustomerID\")\nsonuc = d.groupby(\"Country\", as_index=False)[\"tutar\"].sum().round(2).sort_values(\"tutar\", ascending=False).head(5)", "aciklama": "<p>Tutar kalem seviyesinde, ülke müşteri seviyesinde. Aradaki köprü <code>Orders</code> tablosu: önce kalemleri siparişe (<code>OrderID</code>), sonra siparişi müşteriye (<code>CustomerID</code>) bağlıyoruz.</p><p><code>Orders[[\"OrderID\", \"CustomerID\"]]</code> gibi sadece gereken sütunlarla birleştirmek hem hızlıdır hem de aynı adlı sütunların çakışmasını (<code>_x</code>, <code>_y</code>) önler.</p><p>ABD ve Almanya cironun açık ara en büyük iki pazarı; ikisinin toplamı üçüncü sıradaki Avusturya'nın neredeyse dört katı.</p>", "sirali": true},
  {"id": "w45", "dil": "python", "seviye": 2, "kategori": "Birleştirme", "baslik": "Çalışanların 1997 performansı", "soru": "1997 yılında alınan siparişlerde her çalışanın sipariş sayısını (<code>siparis</code>) ve cirosunu (<code>ciro</code>, 2 ondalık) bul. Çalışanı ad ve soyadı birleştirerek <code>calisan</code> sütununda göster. Ciroya göre azalan sırada <code>sonuc</code>'a ata.", "ipucu": "Önce siparişleri tarihe göre süz, sonra kalemlerle ve çalışanlarla birleştir. Sipariş sayısı için <code>(\"OrderID\", \"nunique\")</code>.", "cozum": "od = OrderDetails.assign(tutar=OrderDetails[\"UnitPrice\"] * OrderDetails[\"Quantity\"] * (1 - OrderDetails[\"Discount\"]))\no97 = Orders[(Orders[\"OrderDate\"] >= \"1997-01-01\") & (Orders[\"OrderDate\"] < \"1998-01-01\")]\nd = od.merge(o97[[\"OrderID\", \"EmployeeID\"]], on=\"OrderID\").merge(Employees[[\"EmployeeID\", \"FirstName\", \"LastName\"]], on=\"EmployeeID\")\nd[\"calisan\"] = d[\"FirstName\"] + \" \" + d[\"LastName\"]\nsonuc = d.groupby(\"calisan\", as_index=False).agg(siparis=(\"OrderID\", \"nunique\"), ciro=(\"tutar\", \"sum\")).round(2).sort_values(\"ciro\", ascending=False)", "aciklama": "<p>Bir sipariş birden fazla kalemden oluştuğu için birleştirme sonrası her sipariş birden çok satırda tekrar eder. Sipariş sayısını <code>count</code> ile değil <code>nunique</code> ile saymak bu yüzden şart: <code>count</code> kalem sayısını verirdi.</p><p>Margaret Peacock hem en çok siparişi alan hem en çok ciro yapan çalışan. Laura Callahan ise Nancy Davolio'ya yakın sayıda sipariş almış ama cirosu belirgin şekilde düşük: siparişleri daha küçük. Sipariş sayısı ile ciroyu yan yana koymak, \"çok iş\" ile \"büyük iş\" arasındaki farkı gösterir.</p>", "sirali": true},
  {"id": "w46", "dil": "python", "seviye": 2, "kategori": "Eksik Veri", "baslik": "Henüz gönderilmemiş siparişler", "soru": "Gönderim tarihi boş olan (<code>ShippedDate</code> eksik) siparişleri bul. Müşteri adını (<code>CompanyName</code>) ekle ve verideki son sipariş tarihine (1998-05-06) göre kaç gündür beklediğini <code>bekleme_gun</code> olarak hesapla. <code>OrderID</code>, <code>CompanyName</code>, <code>OrderDate</code>, <code>bekleme_gun</code> sütunlarını en uzun bekleyen en üstte (eşitlikte OrderID) olacak şekilde <code>sonuc</code>'a ata.", "ipucu": "<code>isnull()</code> ile süz, <code>merge</code> ile müşteri adını ekle, <code>(tarih1 - tarih2).dt.days</code> ile gün farkı.", "cozum": "bekleyen = Orders[Orders[\"ShippedDate\"].isnull()].merge(Customers[[\"CustomerID\", \"CompanyName\"]], on=\"CustomerID\")\nbekleyen[\"bekleme_gun\"] = (pd.Timestamp(\"1998-05-06\") - bekleyen[\"OrderDate\"]).dt.days\nsonuc = bekleyen[[\"OrderID\", \"CompanyName\", \"OrderDate\", \"bekleme_gun\"]].sort_values([\"bekleme_gun\", \"OrderID\"], ascending=[False, True])", "aciklama": "<p>Eksik değer her zaman veri hatası değildir: burada <code>ShippedDate</code>'in boş olması \"henüz gönderilmedi\" demek. Eksikliğin anlamını bilmek, onu doldurmak mı, atmak mı yoksa ayrı bir durum olarak mı ele almak gerektiğini belirler.</p><p>21 sipariş bekliyor, en eskisi 28 gündür. Bugünün tarihi yerine verinin son tarihini (1998-05-06) kullandık. Bugünün tarihiyle hesaplasaydık her sipariş \"on yıllardır bekliyor\" görünürdü.</p>", "sirali": true},
  {"id": "w47", "dil": "python", "seviye": 2, "kategori": "Dönüşüm", "baslik": "Fiyat gruplarına göre ürünler", "soru": "Ürünleri birim fiyata göre gruplara ayır: 10'dan az <code>Ucuz</code>, 10-30 <code>Orta</code>, 30-60 <code>Pahalı</code>, 60 ve üzeri <code>Lüks</code> (alt sınır dahil). Her grubun ürün sayısını (<code>urun</code>) ve ortalama stok miktarını (<code>ort_stok</code>, 1 ondalık) gruplar sırasıyla <code>sonuc</code>'a ata.", "ipucu": "<code>pd.cut(..., bins=[0, 10, 30, 60, 1000], right=False, labels=[...])</code>", "cozum": "Products[\"fiyat_grubu\"] = pd.cut(Products[\"UnitPrice\"], bins=[0, 10, 30, 60, 1000], right=False, labels=[\"Ucuz\", \"Orta\", \"Pahalı\", \"Lüks\"])\nsonuc = Products.groupby(\"fiyat_grubu\", observed=True).agg(urun=(\"ProductID\", \"count\"), ort_stok=(\"UnitsInStock\", \"mean\")).round(1)", "aciklama": "<p><code>right=False</code> aralıkları sol kapalı yapar: [10, 30). Böylece fiyatı tam 30 olan ürün \"Pahalı\" grubuna girer. Varsayılan <code>right=True</code> ile \"Orta\"da kalırdı.</p><p>Gruplar sıralı kategorik bir sütun olduğu için <code>groupby</code> sonucu Ucuz → Lüks sırasıyla gelir. <code>observed=True</code> boş kalan grupları göstermez.</p><p>Ürünlerin yarısından fazlası (41) Orta grupta. Pahalı ve lüks ürünlerin ortalama stoğu ucuz ve orta ürünlerin yaklaşık yarısı: pahalı ürünler daha az stokta tutuluyor.</p>", "sirali": true},
  {"id": "w48", "dil": "python", "seviye": 2, "kategori": "Gruplama", "baslik": "Kategori özeti (named aggregation)", "soru": "Her kategori için ürün sayısını (<code>urun</code>), ortalama fiyatı (<code>ort_fiyat</code>), toplam stoğu (<code>toplam_stok</code>) ve satıştan kalkan ürün sayısını (<code>satistan_kalkan</code>) bul, sayılar 2 ondalık. Kategori adlarını <code>Categories</code> tablosundan al. Ürün sayısına göre azalan sırada <code>sonuc</code>'a ata.", "ipucu": "<code>agg(urun=(\"ProductID\", \"count\"), ...)</code>. Discontinued 1/0 olduğu için <code>sum</code> satıştan kalkanları sayar.", "cozum": "d = Products.merge(Categories[[\"CategoryID\", \"CategoryName\"]], on=\"CategoryID\")\nsonuc = d.groupby(\"CategoryName\").agg(urun=(\"ProductID\", \"count\"), ort_fiyat=(\"UnitPrice\", \"mean\"), toplam_stok=(\"UnitsInStock\", \"sum\"), satistan_kalkan=(\"Discontinued\", \"sum\")).round(2).sort_values(\"urun\", ascending=False)", "aciklama": "<p>Named aggregation (<code>yeni_ad=(\"sütun\", \"fonksiyon\")</code>) farklı sütunlara farklı hesaplar uygulayıp sonuç sütunlarına anlamlı adlar vermenin en okunaklı yolu.</p><p>1/0 kodlu bir sütunun toplamı 1'lerin sayısıdır: <code>Discontinued</code> için <code>sum</code> satıştan kalkan ürün sayısını verir. Aynı hile ortalamayla oranı verir.</p><p>Meat/Poultry en pahalı kategori ve 6 ürününden 4'ü satıştan kalkmış: ürün gamı en çok daralan kategori.</p>", "sirali": true},
  {"id": "w49", "dil": "python", "seviye": 3, "kategori": "Birleştirme", "baslik": "En çok ciro getiren tedarikçiler", "soru": "Her tedarikçinin ürünlerinin toplam satış cirosunu (<code>ciro</code>, kalem tutarı = <code>UnitPrice × Quantity × (1 − Discount)</code>, 2 ondalık) ve satılan farklı ürün sayısını (<code>urun</code>) bul. Tedarikçinin adı (<code>CompanyName</code>) ve ülkesiyle (<code>Country</code>) birlikte, ciroya göre ilk 5'i <code>sonuc</code>'a ata.", "ipucu": "OrderDetails → Products (ProductID) → Suppliers (SupplierID). Gruplamada iki sütun: ad ve ülke.", "cozum": "od = OrderDetails.assign(tutar=OrderDetails[\"UnitPrice\"] * OrderDetails[\"Quantity\"] * (1 - OrderDetails[\"Discount\"]))\nd = od.merge(Products[[\"ProductID\", \"SupplierID\"]], on=\"ProductID\").merge(Suppliers[[\"SupplierID\", \"CompanyName\", \"Country\"]], on=\"SupplierID\")\nsonuc = d.groupby([\"CompanyName\", \"Country\"], as_index=False).agg(urun=(\"ProductID\", \"nunique\"), ciro=(\"tutar\", \"sum\")).round(2).sort_values(\"ciro\", ascending=False).head(5)", "aciklama": "<p>İki adımlı bir köprü: kalemler ürünlere, ürünler tedarikçilere bağlanıyor. Zincirleme <code>merge</code> ile her adımı ayrı ayrı yazmak hata ayıklamayı kolaylaştırır.</p><p>Gruplamaya ülkeyi de eklemek sonucu değiştirmez (her tedarikçinin tek ülkesi var), ama ülke bilgisini sonuçta tutmanın kısa yoludur.</p><p>İlk sıradaki Aux joyeux ecclésiastiques sadece 2 ürünle en çok ciroyu getiriyor: ürünlerinden biri Northwind'in en pahalı ürünü Côte de Blaye. Tedarikçi değerini ürün sayısı değil, ürünlerin ne kadar sattığı belirliyor.</p>", "sirali": true},
  {"id": "w50", "dil": "python", "seviye": 3, "kategori": "Tarih", "baslik": "Sadık müşterilerin sipariş sıklığı", "soru": "Her müşteri için sipariş sayısını (<code>siparis</code>), ilk ve son sipariş tarihini (<code>ilk</code>, <code>son</code>), ikisi arasındaki gün sayısını (<code>aktif_gun</code>) ve siparişler arası ortalama gün sayısını (<code>ort_aralik</code> = aktif_gun / (siparis − 1), 1 ondalık) hesapla. En az 15 siparişi olan müşterileri, ortalama aralığa göre artan (eşitlikte sipariş sayısı çok olan önce) sırada <code>sonuc</code>'a ata.", "ipucu": "<code>groupby(\"CustomerID\").agg(siparis=..., ilk=(\"OrderDate\", \"min\"), son=(\"OrderDate\", \"max\"))</code>", "cozum": "m = Orders.groupby(\"CustomerID\").agg(siparis=(\"OrderID\", \"count\"), ilk=(\"OrderDate\", \"min\"), son=(\"OrderDate\", \"max\"))\nm[\"aktif_gun\"] = (m[\"son\"] - m[\"ilk\"]).dt.days\nm[\"ort_aralik\"] = (m[\"aktif_gun\"] / (m[\"siparis\"] - 1)).round(1)\nsonuc = m[m[\"siparis\"] >= 15].sort_values([\"ort_aralik\", \"siparis\"], ascending=[True, False])", "aciklama": "<p>Tarih sütunlarında <code>min</code> ve <code>max</code> ilk ve son tarihi verir; farkları bir <code>Timedelta</code> sütunudur ve <code>.dt.days</code> ile güne çevrilir.</p><p>n sipariş arasında n − 1 aralık vardır; bu yüzden ortalama aralık <code>aktif_gun / (siparis − 1)</code>. Sık yapılan hata <code>siparis</code>'e bölmek.</p><p>SAVEA (Save-a-lot Markets) ortalama 19 günde bir sipariş veriyor. Bu tür bir metrik, \"her zamanki aralığının iki katı süredir sipariş vermeyen müşteriler\" gibi kayıp uyarıları kurmanın temelidir.</p>", "sirali": true},
  {"id": "w51", "dil": "python", "seviye": 3, "kategori": "Tarih", "baslik": "1997 aylık ciro ve aydan aya değişim", "soru": "1997 yılının her ayı için cirosunu (<code>ciro</code>, tam sayıya yuvarlanmış) ve bir önceki aya göre yüzde değişimi (<code>degisim_yuzde</code>, 1 ondalık) bul. Ocak 1997'nin değişimi Aralık 1996'ya göre hesaplanmalı. Sonucu aylar sırasıyla <code>sonuc</code>'a ata.", "ipucu": "Aylık ciroyu <b>tüm</b> yıllar için hesapla, <code>pct_change()</code> uygula, sonra 1997'yi süz. Önce süzersen Ocak'ın önceki ayı kalmaz.", "cozum": "od = OrderDetails.assign(tutar=OrderDetails[\"UnitPrice\"] * OrderDetails[\"Quantity\"] * (1 - OrderDetails[\"Discount\"]))\nd = od.merge(Orders[[\"OrderID\", \"OrderDate\"]], on=\"OrderID\")\naylik = d.groupby(d[\"OrderDate\"].dt.to_period(\"M\"))[\"tutar\"].sum()\ndegisim = (aylik.pct_change() * 100).round(1)\nyil = aylik.index.year == 1997\nsonuc = pd.DataFrame({\"ciro\": aylik[yil].round(0), \"degisim_yuzde\": degisim[yil]})", "aciklama": "<p><code>dt.to_period(\"M\")</code> tarihleri aya çevirir; bu sütuna göre gruplamak aylık toplamı verir. <code>pct_change()</code> her değeri bir öncekiyle karşılaştırır: (bu ay − önceki ay) / önceki ay.</p><p>İşlemlerin sırası önemli. Önce 1997'yi süzüp sonra <code>pct_change</code> yapsaydık Ocak'ın değişimi boş (NaN) olurdu, çünkü süzülmüş veride önceki ay yok. Önce değişimi tüm veride hesaplayıp sonra süzmek doğru sonucu verir.</p><p>Aylık ciro çok dalgalı: Aralık'ta %64 artış, Kasım'da %35 düşüş var. Bu kadar dalgalı bir seride tek bir ayın değişimine bakarak yorum yapmak yanıltıcı olur; hareketli ortalama ya da geçen yılın aynı ayıyla karşılaştırma daha sağlıklıdır.</p>", "sirali": true},
  {"id": "w52", "dil": "python", "seviye": 3, "kategori": "Segmentasyon", "baslik": "Müşteri değer segmentleri", "soru": "Her müşterinin toplam cirosunu ve sipariş sayısını hesapla. Müşterileri ciroya göre <code>pd.qcut</code> ile 4 eşit gruba ayır: en düşük <code>D</code> … en yüksek <code>A</code>. Her segmentin müşteri sayısını (<code>musteri</code>), ortalama sipariş sayısını (<code>ort_siparis</code>, 1 ondalık) ve toplam ciro içindeki payını (<code>ciro_pay</code>, %, 1 ondalık) A'dan D'ye sıralı olarak <code>sonuc</code>'a ata.", "ipucu": "<code>pd.qcut(m[\"ciro\"], 4, labels=[\"D\", \"C\", \"B\", \"A\"])</code>, sonra segment bazında named aggregation.", "cozum": "od = OrderDetails.assign(tutar=OrderDetails[\"UnitPrice\"] * OrderDetails[\"Quantity\"] * (1 - OrderDetails[\"Discount\"]))\nm = od.merge(Orders[[\"OrderID\", \"CustomerID\"]], on=\"OrderID\").groupby(\"CustomerID\").agg(siparis=(\"OrderID\", \"nunique\"), ciro=(\"tutar\", \"sum\"))\nm[\"segment\"] = pd.qcut(m[\"ciro\"], 4, labels=[\"D\", \"C\", \"B\", \"A\"])\nozet = m.groupby(\"segment\", observed=True).agg(musteri=(\"ciro\", \"size\"), ort_siparis=(\"siparis\", \"mean\"), toplam_ciro=(\"ciro\", \"sum\"))\nozet[\"ciro_pay\"] = (100 * ozet[\"toplam_ciro\"] / ozet[\"toplam_ciro\"].sum()).round(1)\nsonuc = ozet.drop(columns=\"toplam_ciro\").round(1).sort_index(ascending=False)", "aciklama": "<p><code>qcut</code> sınırları verinin kendisinden belirler: her grupta yaklaşık aynı sayıda müşteri olur (89 müşteri → 22, 22, 22, 23).</p><p>A segmenti, müşterilerin dörtte biriyle cironun üçte ikisini getiriyor; D segmenti ise sadece %3'ünü. Klasik Pareto yoğunlaşması. Satış ekibinin zamanını, kampanya bütçesini ya da kişisel ilgiyi A segmentine öncelikli ayırmak bu tablodan çıkan doğal karar.</p><p>Segmentler arasında sipariş sayısı da düzenli olarak artıyor: değerli müşteriler hem daha sık hem daha çok alıyor.</p>", "sirali": true},
  // ───────── Ek: kolay SQL ve Python (NumPy, saf Python) ─────────
  {"id": "w53", "dil": "sql", "seviye": 1, "kategori": "Temel SELECT", "baslik": "Kategori listesi", "soru": "Bütün ürün kategorilerinin adını (<code>CategoryName</code>) ve açıklamasını (<code>Description</code>) kategori adına göre alfabetik sırayla getir.", "ipucu": "Sadece iki sütun seç, <code>ORDER BY CategoryName</code>.", "cozum": "SELECT CategoryName, Description\nFROM Categories\nORDER BY CategoryName;", "aciklama": "<p>En temel sorgu kalıbı: hangi sütunlar (<code>SELECT</code>), hangi tablodan (<code>FROM</code>), hangi sırayla (<code>ORDER BY</code>). Varsayılan sıralama küçükten büyüğe, metinlerde alfabetiktir.</p><p>Northwind 8 kategoride gıda ürünü satıyor. Kategori tablosu küçük bir \"sözlük\" tablosu: ürünler kategoriye <code>CategoryID</code> ile bağlanıyor.</p>", "sirali": true},
  {"id": "w54", "dil": "sql", "seviye": 1, "kategori": "Temel SELECT", "baslik": "En pahalı 5 ürün", "soru": "Birim fiyatı (<code>UnitPrice</code>) en yüksek 5 ürünün adını ve fiyatını, en pahalı en üstte olacak şekilde getir.", "ipucu": "<code>ORDER BY UnitPrice DESC</code> ve <code>LIMIT 5</code>.", "cozum": "SELECT ProductName, UnitPrice\nFROM Products\nORDER BY UnitPrice DESC\nLIMIT 5;", "aciklama": "<p><code>DESC</code> büyükten küçüğe sıralar, <code>LIMIT</code> ilk n satırı alır. \"En …\" sorularının temel kalıbı.</p><p>En pahalı ürün Côte de Blaye (263,50), ikincisinin iki katından fazla. Ortalama fiyatı hesaplarken bu tek ürün ortalamayı belirgin şekilde yukarı çeker.</p><p><b>SQL Server notu:</b> <code>LIMIT 5</code> yerine <code>SELECT TOP 5 ...</code>.</p>", "sirali": true},
  {"id": "w55", "dil": "sql", "seviye": 1, "kategori": "Filtreleme", "baslik": "Londra'daki müşteriler", "soru": "Londra'daki (<code>City</code> = London) müşterilerin şirket adını, iletişim kişisini ve unvanını şirket adına göre sıralı getir.", "ipucu": "<code>WHERE City = 'London'</code>. Metinler tek tırnak içinde yazılır.", "cozum": "SELECT CompanyName, ContactName, ContactTitle\nFROM Customers\nWHERE City = 'London'\nORDER BY CompanyName;", "aciklama": "<p><code>WHERE</code> sadece koşulu sağlayan satırları tutar. Metin karşılaştırmasında değer tek tırnak içinde yazılır; çift tırnak birçok veritabanında sütun adı anlamına gelir.</p><p>Londra'da 6 müşteri var. İletişim kişilerinin hepsi satış tarafında (Sales Representative, Sales Agent…): Northwind'in muhatabı müşterilerin satın alma ekipleri.</p>", "sirali": true},
  {"id": "w56", "dil": "sql", "seviye": 1, "kategori": "Filtreleme", "baslik": "Avrupalı tedarikçiler (IN)", "soru": "Almanya, Fransa veya İtalya'daki tedarikçilerin adını ve ülkesini, önce ülkeye sonra ada göre sıralı getir.", "ipucu": "<code>WHERE Country IN ('Germany', 'France', 'Italy')</code>", "cozum": "SELECT CompanyName, Country\nFROM Suppliers\nWHERE Country IN ('Germany', 'France', 'Italy')\nORDER BY Country, CompanyName;", "aciklama": "<p><code>IN</code>, aynı sütun için birden fazla <code>OR</code> yazmanın kısa yolu: <code>Country = 'Germany' OR Country = 'France' OR ...</code> ile aynı sonucu verir, ama çok daha okunaklıdır.</p><p>Üç ülkede toplam 8 tedarikçi var. <code>ORDER BY Country, CompanyName</code>: önce ülkeye göre, aynı ülkedekiler kendi içinde ada göre sıralanır.</p>", "sirali": true},
  {"id": "w57", "dil": "sql", "seviye": 1, "kategori": "Filtreleme", "baslik": "Fiyatı 20-30 arası ürünler", "soru": "Birim fiyatı 20 ile 30 arasında (iki uç dahil) olan ürünlerin adını ve fiyatını, fiyata göre artan (eşitlikte ada göre) sırada getir.", "ipucu": "<code>WHERE UnitPrice BETWEEN 20 AND 30</code>", "cozum": "SELECT ProductName, UnitPrice\nFROM Products\nWHERE UnitPrice BETWEEN 20 AND 30\nORDER BY UnitPrice, ProductName;", "aciklama": "<p><code>BETWEEN a AND b</code> iki ucu da dahil eder: <code>UnitPrice &gt;= 20 AND UnitPrice &lt;= 30</code> ile aynıdır. Fiyatı tam 20 olan Maxilaku ve tam 30 olan Uncle Bob's sonuçta.</p><p>İki ürünün fiyatı aynı (21,00). İkinci sıralama kriteri (ürün adı) olmasaydı bu ikisinin sırası belirsiz olurdu.</p>", "sirali": true},
  {"id": "w58", "dil": "sql", "seviye": 1, "kategori": "Filtreleme", "baslik": "Sahibiyle görüşülen müşteriler", "soru": "İletişim kişisinin unvanı (<code>ContactTitle</code>) \"Owner\" olan müşterilerin şirket adını, iletişim kişisini ve ülkesini önce ülkeye sonra şirket adına göre sıralı getir.", "ipucu": "<code>WHERE ContactTitle = 'Owner'</code>", "cozum": "SELECT CompanyName, ContactName, Country\nFROM Customers\nWHERE ContactTitle = 'Owner'\nORDER BY Country, CompanyName;", "aciklama": "<p>17 müşteride doğrudan işletme sahibiyle görüşülüyor. Bunlar genelde küçük işletmeler (bistro, restoran, şarküteri): karar verici tek kişi, satış süreci daha kısa.</p><p>Eşittir (<code>=</code>) tam eşleşme arar. Unvanında \"Owner\" <i>geçen</i> herkesi (örn. \"Owner/Marketing Assistant\") bulmak isteseydik <code>LIKE '%Owner%'</code> kullanırdık.</p>", "sirali": true},
  {"id": "w59", "dil": "sql", "seviye": 1, "kategori": "Eksik Veri", "baslik": "Faksı olmayan müşteriler", "soru": "Toplam müşteri sayısını (<code>musteri</code>), faks numarası kayıtlı olanların sayısını (<code>faksi_olan</code>) ve olmayanların sayısını (<code>faksi_olmayan</code>) tek satırda getir.", "ipucu": "<code>COUNT(*)</code> tüm satırları, <code>COUNT(Fax)</code> sadece Fax'ı boş olmayanları sayar.", "cozum": "SELECT COUNT(*) AS musteri,\n       COUNT(Fax) AS faksi_olan,\n       COUNT(*) - COUNT(Fax) AS faksi_olmayan\nFROM Customers;", "aciklama": "<p><code>COUNT(sütun)</code> NULL değerleri saymaz. Bu yüzden <code>COUNT(*) - COUNT(sütun)</code> o sütundaki eksik değer sayısını verir. Bir tablonun eksik veri durumunu tek sorguda görmenin pratik yolu.</p><p>91 müşteriden 22'sinin faks numarası yok.</p>"},
  {"id": "w60", "dil": "sql", "seviye": 1, "kategori": "Temel SELECT", "baslik": "Gönderim yapılan ülkeler", "soru": "Siparişlerin gönderildiği farklı ülkeleri (<code>ShipCountry</code>), her ülke bir kez görünecek şekilde alfabetik sırayla getir.", "ipucu": "<code>SELECT DISTINCT</code>", "cozum": "SELECT DISTINCT ShipCountry\nFROM Orders\nORDER BY ShipCountry;", "aciklama": "<p>830 siparişte ülke adları defalarca tekrar ediyor. <code>DISTINCT</code> her farklı değeri bir kez gösterir: Northwind 21 ülkeye gönderim yapmış.</p><p>Aynı sonuç <code>GROUP BY ShipCountry</code> ile de alınır. Fark: <code>GROUP BY</code> ile yanına <code>COUNT(*)</code> gibi özetler eklenebilir.</p>", "sirali": true},
  {"id": "w61", "dil": "sql", "seviye": 1, "kategori": "Aggregation", "baslik": "Sipariş dönemi", "soru": "Toplam sipariş sayısını (<code>siparis</code>), ilk sipariş tarihini (<code>ilk_siparis</code>) ve son sipariş tarihini (<code>son_siparis</code>) tek satırda getir.", "ipucu": "<code>COUNT(*)</code>, <code>MIN(OrderDate)</code>, <code>MAX(OrderDate)</code>", "cozum": "SELECT COUNT(*) AS siparis,\n       MIN(OrderDate) AS ilk_siparis,\n       MAX(OrderDate) AS son_siparis\nFROM Orders;", "aciklama": "<p>Yeni bir veri setine başlarken ilk bakılacaklardan biri verinin hangi dönemi kapsadığı. <code>MIN</code> ve <code>MAX</code> tarihlerde de çalışır.</p><p>Veri 4 Temmuz 1996 ile 6 Mayıs 1998 arasını kapsıyor. Yani 1996 ve 1998 tam yıl değil; yıllık karşılaştırmalarda sadece 1997 tam yıl. \"1998'de satışlar düştü\" gibi bir yorum yapmadan önce bunu bilmek gerekir.</p>"},
  {"id": "w62", "dil": "sql", "seviye": 1, "kategori": "Aggregation", "baslik": "Fiyat özeti", "soru": "Ürün sayısını (<code>urun</code>), ortalama birim fiyatı (<code>ort_fiyat</code>, 2 ondalık), en düşük (<code>en_ucuz</code>) ve en yüksek (<code>en_pahali</code>) fiyatı tek satırda getir.", "ipucu": "<code>COUNT</code>, <code>AVG</code>, <code>MIN</code>, <code>MAX</code> ve <code>ROUND(…, 2)</code>.", "cozum": "SELECT COUNT(*) AS urun,\n       ROUND(AVG(UnitPrice), 2) AS ort_fiyat,\n       MIN(UnitPrice) AS en_ucuz,\n       MAX(UnitPrice) AS en_pahali\nFROM Products;", "aciklama": "<p>Toplama fonksiyonları birçok satırı tek değere indirir. <code>GROUP BY</code> olmadan kullanıldığında tüm tablo tek bir grup sayılır ve sonuç tek satırdır.</p><p>Ortalama fiyat 28,87, en ucuz ürün 2,50, en pahalısı 263,50. En pahalı ürün ortalamanın 9 katından fazla: tek bir uç değer ortalamayı yukarı çekiyor.</p>"},
  {"id": "w63", "dil": "sql", "seviye": 1, "kategori": "Aggregation", "baslik": "En çok sipariş giden 5 ülke", "soru": "Her gönderim ülkesine kaç sipariş gittiğini say. En çok siparişi olan 5 ülkeyi sipariş sayısına göre azalan (eşitlikte ülke adına göre) sırada getir. Sütunlar: <code>ShipCountry</code>, <code>siparis</code>.", "ipucu": "<code>GROUP BY ShipCountry</code>, <code>COUNT(*)</code>, sonra sıralama ve <code>LIMIT</code>.", "cozum": "SELECT ShipCountry, COUNT(*) AS siparis\nFROM Orders\nGROUP BY ShipCountry\nORDER BY siparis DESC, ShipCountry\nLIMIT 5;", "aciklama": "<p><code>GROUP BY</code> her ülke için ayrı bir grup oluşturur, <code>COUNT(*)</code> her grubun satır sayısını verir.</p><p>Almanya ve ABD 122'şer siparişle eşit. İkinci kriter (ülke adı) olmasaydı hangisinin önce geleceği belirsiz olurdu.</p>", "sirali": true},
  {"id": "w64", "dil": "sql", "seviye": 1, "kategori": "Temel SELECT", "baslik": "Stok değeri en yüksek ürünler", "soru": "Her ürün için stok değerini (<code>stok_degeri</code> = <code>UnitPrice × UnitsInStock</code>, 2 ondalık) hesapla. Stok değeri en yüksek 5 ürünün adını, fiyatını, stok miktarını ve stok değerini büyükten küçüğe getir.", "ipucu": "Hesaplanan sütuna <code>AS</code> ile ad ver, <code>ORDER BY</code>'da o adı kullan.", "cozum": "SELECT ProductName, UnitPrice, UnitsInStock,\n       ROUND(UnitPrice * UnitsInStock, 2) AS stok_degeri\nFROM Products\nORDER BY stok_degeri DESC\nLIMIT 5;", "aciklama": "<p>Sütunlarla aritmetik işlem yapılabilir; sonuç tabloya yazılmaz, sadece sorgu sonucunda görünür. <code>ORDER BY</code>, <code>SELECT</code>'ten sonra çalıştığı için takma adı (<code>stok_degeri</code>) tanır.</p><p>Côte de Blaye sadece 17 adet stokla ilk sırada, Sirop d'érable ise 113 adetle beşinci. Stoğa bağlanan para, adetten çok fiyata bağlı.</p>", "sirali": true},
  {"id": "w65", "dil": "sql", "seviye": 1, "kategori": "Tarih", "baslik": "Aralık 1997 siparişleri", "soru": "Aralık 1997'de verilen sipariş sayısını <code>siparis</code> sütununda getir.", "ipucu": "Tarih aralığını yarı açık yaz: <code>&gt;= '1997-12-01' AND &lt; '1998-01-01'</code>.", "cozum": "SELECT COUNT(*) AS siparis\nFROM Orders\nWHERE OrderDate >= '1997-12-01' AND OrderDate < '1998-01-01';", "aciklama": "<p>Tarihler <code>YYYY-MM-DD</code> biçiminde saklandığı için metin olarak karşılaştırmak doğru çalışır.</p><p>Aralığı \"başlangıç dahil, bitiş hariç\" yazmak (<code>&lt; '1998-01-01'</code>) en güvenli yol. <code>&lt;= '1997-12-31'</code> yazsaydık, saat bilgisi olan bir sütunda 31 Aralık gün içindeki siparişler dışarıda kalırdı.</p><p>Aralık 1997'de 48 sipariş var.</p>"},
  {"id": "w66", "dil": "sql", "seviye": 1, "kategori": "CASE WHEN", "baslik": "Stok durumu", "soru": "Ürünleri stok miktarına göre gruplara ayır: 0 ise <code>Tükendi</code>, 20'den az ise <code>Az</code>, diğerleri <code>Yeterli</code>. Her grupta kaç ürün olduğunu bul. Sütunlar: <code>stok_durumu</code>, <code>urun</code>. Ürün sayısına göre azalan.", "ipucu": "<code>CASE WHEN … THEN … END</code> ile yeni sütun üret, ona göre grupla.", "cozum": "SELECT CASE\n         WHEN UnitsInStock = 0 THEN 'Tükendi'\n         WHEN UnitsInStock < 20 THEN 'Az'\n         ELSE 'Yeterli'\n       END AS stok_durumu,\n       COUNT(*) AS urun\nFROM Products\nGROUP BY stok_durumu\nORDER BY urun DESC;", "aciklama": "<p><code>CASE</code> koşulları yukarıdan aşağı dener, ilk doğru olanı alır. İkinci koşulda <code>UnitsInStock &gt; 0 AND UnitsInStock &lt; 20</code> yazmaya gerek yok: stoğu 0 olanlar zaten ilk satırda yakalandı.</p><p>5 ürün tükenmiş, 21 ürünün stoğu az. Bu basit tablo bir stok raporunun ilk satırı olabilir.</p>", "sirali": true},
  {"id": "w67", "dil": "python", "seviye": 1, "kategori": "pandas Temelleri", "baslik": "Ürünlerin sayısal özeti", "soru": "<code>UnitPrice</code>, <code>UnitsInStock</code> ve <code>UnitsOnOrder</code> sütunlarının betimsel istatistiklerini (2 ondalık) <code>sonuc</code>'a ata.", "ipucu": "Sütunları liste ile seç, <code>describe().round(2)</code>.", "cozum": "sonuc = Products[[\"UnitPrice\", \"UnitsInStock\", \"UnitsOnOrder\"]].describe().round(2)", "aciklama": "<p><code>describe()</code> sayı, ortalama, standart sapma, en küçük, çeyrekler ve en büyük değeri tek tabloda verir.</p><p><code>UnitsOnOrder</code>'da medyan ve 3. çeyrek 0: ürünlerin dörtte üçünden fazlası için açık bir sipariş yok. Ortalama (10,13) bu yüzden yanıltıcı; birkaç ürünün büyük siparişi ortalamayı yukarı çekiyor.</p>"},
  {"id": "w68", "dil": "python", "seviye": 1, "kategori": "Filtreleme", "baslik": "Stoğu kritik seviyenin altındaki ürünler", "soru": "Satışta olan (<code>Discontinued</code> = 0) ve stoğu yeniden sipariş seviyesinin (<code>ReorderLevel</code>) altında kalan ürünlerin <code>ProductName</code>, <code>UnitsInStock</code>, <code>ReorderLevel</code>, <code>UnitsOnOrder</code> sütunlarını stoğa göre artan (eşitlikte ada göre) sırada <code>sonuc</code>'a ata.", "ipucu": "İki sütunu birbiriyle karşılaştırabilirsin: <code>Products[\"UnitsInStock\"] &lt; Products[\"ReorderLevel\"]</code>.", "cozum": "sonuc = Products.loc[(Products[\"UnitsInStock\"] < Products[\"ReorderLevel\"]) & (Products[\"Discontinued\"] == 0), [\"ProductName\", \"UnitsInStock\", \"ReorderLevel\", \"UnitsOnOrder\"]].sort_values([\"UnitsInStock\", \"ProductName\"])", "aciklama": "<p>Koşul bir sabitle değil başka bir sütunla karşılaştırma yapıyor: her satırda kendi stoğu kendi kritik seviyesiyle karşılaştırılır.</p><p>18 ürün kritik seviyenin altında. Çoğunun yolda siparişi var (<code>UnitsOnOrder</code> &gt; 0), ama Nord-Ost Matjeshering için hiç sipariş verilmemiş: satın alma ekibinin ilk bakması gereken satır bu.</p>", "sirali": true},
  {"id": "w69", "dil": "python", "seviye": 1, "kategori": "NumPy", "baslik": "Stokta var mı? (np.where)", "soru": "<code>np.where</code> ile her ürün için <code>stok</code> sütunu oluştur: stok 0'dan büyükse <code>Stokta var</code>, değilse <code>Stokta yok</code>. Her grubun ürün sayısını (<code>urun</code>) ve ortalama fiyatını (<code>ort_fiyat</code>, 2 ondalık) <code>sonuc</code>'a ata.", "ipucu": "<code>np.where(koşul, doğruysa, yanlışsa)</code>, sonra <code>groupby(...).agg(...)</code>.", "cozum": "Products[\"stok\"] = np.where(Products[\"UnitsInStock\"] > 0, \"Stokta var\", \"Stokta yok\")\nsonuc = Products.groupby(\"stok\").agg(urun=(\"ProductID\", \"count\"), ort_fiyat=(\"UnitPrice\", \"mean\")).round(2)", "aciklama": "<p><code>np.where</code> iki seçenekli koşullu değer atamanın en hızlı yolu; Excel'deki <code>EĞER</code>, SQL'deki iki dallı <code>CASE WHEN</code>.</p><p>Tükenen 5 ürünün ortalama fiyatı (45,89), stokta olanlarınkinin (27,68) belirgin şekilde üstünde. Pahalı ürünlerin stokta tutulmaması bilinçli bir tercih mi, yoksa tedarik sorunu mu? Veri bir soruyu cevaplarken yenisini doğuruyor.</p>"},
  {"id": "w70", "dil": "python", "seviye": 2, "kategori": "NumPy", "baslik": "İndirim grupları (np.select)", "soru": "Sipariş kalemlerini indirime göre üç gruba ayır: indirim 0 ise <code>İndirimsiz</code>, %10 ve altı ise <code>Düşük (≤%10)</code>, üstü <code>Yüksek (&gt;%10)</code>. Her grubun kalem sayısını (<code>kalem</code>) ve ortalama adedini (<code>ort_adet</code>, 1 ondalık) <code>sonuc</code>'a ata.", "ipucu": "<code>np.select(koşul_listesi, değer_listesi, default=...)</code>. Koşulların sırası önemli.", "cozum": "kosullar = [OrderDetails[\"Discount\"] == 0, OrderDetails[\"Discount\"] <= 0.1]\nOrderDetails[\"indirim\"] = np.select(kosullar, [\"İndirimsiz\", \"Düşük (≤%10)\"], default=\"Yüksek (>%10)\")\nsonuc = OrderDetails.groupby(\"indirim\").agg(kalem=(\"OrderID\", \"count\"), ort_adet=(\"Quantity\", \"mean\")).round(1)", "aciklama": "<p><code>np.select</code> çok seçenekli <code>CASE WHEN</code>'in NumPy karşılığı: ilk doğru koşulun değeri seçilir. Bu yüzden <code>Discount == 0</code> koşulu <code>&lt;= 0.1</code>'den önce olmalı; tersi olsaydı indirimsiz kalemler de \"Düşük\" grubuna düşerdi.</p><p>İndirimli kalemlerde ortalama adet daha yüksek (yüksek indirimde 27,9, indirimsizde 21,7). İndirim mi daha çok aldırıyor, yoksa büyük siparişlere mi indirim yapılıyor? Bu tablo ikisini ayırt etmeye yetmez.</p>"},
  {"id": "w71", "dil": "python", "seviye": 2, "kategori": "NumPy", "baslik": "Navlun yüzdelikleri", "soru": "Navlun ücretlerini (<code>Freight</code>) NumPy dizisine çevir. 50., 75., 90. ve 99. yüzdelikleri (2 ondalık), indeksi <code>P50</code>, <code>P75</code>, <code>P90</code>, <code>P99</code> olan bir Series olarak <code>sonuc</code>'a ata.", "ipucu": "<code>np.percentile(dizi, [50, 75, 90, 99])</code>", "cozum": "f = Orders[\"Freight\"].to_numpy()\nsonuc = pd.Series(np.percentile(f, [50, 75, 90, 99]).round(2), index=[\"P50\", \"P75\", \"P90\", \"P99\"], name=\"navlun\")", "aciklama": "<p>Yüzdelik, verinin o yüzdesinin altında kaldığı değerdir: siparişlerin yarısının navlunu 41,36'nın altında (medyan).</p><p>P90 (188) ile P99 (643) arasındaki büyük sıçrama dağılımın sağa çok çarpık olduğunu gösteriyor: birkaç sipariş çok yüksek navlunlu. Ortalama yerine yüzdeliklerle raporlamak böyle verilerde daha dürüst bir tablo çizer.</p>"},
  {"id": "w72", "dil": "python", "seviye": 2, "kategori": "Tarih", "baslik": "Haftanın günlerine göre siparişler", "soru": "Her siparişin haftanın hangi gününe denk geldiğini bul. Pazartesiden pazara her gün için sipariş sayısını (hiç sipariş olmayan günler 0 olacak şekilde) <code>sonuc</code>'a ata.", "ipucu": "<code>dt.day_name()</code>, <code>value_counts()</code>, sonra <code>reindex(gün_listesi, fill_value=0)</code>.", "cozum": "gun = Orders[\"OrderDate\"].dt.day_name()\nsira = [\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\", \"Sunday\"]\nsonuc = gun.value_counts().reindex(sira, fill_value=0).rename(\"siparis\")", "aciklama": "<p><code>value_counts</code> sadece veride geçen değerleri sayar. <code>reindex</code> hem istediğimiz sırayı (Pazartesi → Pazar) verir hem de veride hiç olmayan değerleri <code>fill_value</code> ile ekler.</p><p>Hafta sonu hiç sipariş yok ve hafta içi günler neredeyse eşit (164-168). Northwind bir B2B (şirketten şirkete) toptancı: müşterileri iş günlerinde sipariş veriyor.</p>", "sirali": true},
  {"id": "w73", "dil": "python", "seviye": 3, "kategori": "NumPy", "baslik": "Aşırı navlunlu siparişler (z-skoru)", "soru": "Navlun ücretinin z-skorunu hesapla: <code>(değer − ortalama) / standart sapma</code> (NumPy ile). Mutlak z-skoru 3'ten büyük olan siparişlerin <code>OrderID</code>, <code>ShipCountry</code>, <code>Freight</code> ve <code>z</code> (2 ondalık) bilgilerini navluna göre azalan sırada <code>sonuc</code>'a ata.", "ipucu": "<code>f = Orders[\"Freight\"].to_numpy()</code>, <code>z = (f - f.mean()) / f.std()</code>, filtre için <code>np.abs(z) &gt; 3</code>.", "cozum": "f = Orders[\"Freight\"].to_numpy()\nz = (f - f.mean()) / f.std()\nOrders[\"z\"] = z.round(2)\nsonuc = Orders.loc[np.abs(z) > 3, [\"OrderID\", \"ShipCountry\", \"Freight\", \"z\"]].sort_values(\"Freight\", ascending=False)", "aciklama": "<p>z-skoru bir değerin ortalamadan kaç standart sapma uzakta olduğunu söyler. Normal dağılımda değerlerin %99,7'si ±3 aralığındadır; dışarıdakiler uç değer adayıdır.</p><p>17 sipariş eşiği aşıyor, en uçtakinin z-skoru neredeyse 8. Ama dikkat: navlun dağılımı çok çarpık olduğu için normal dağılım varsayımı burada zayıf. Çarpık verilerde IQR ya da yüzdelik tabanlı yöntemler (önceki soru) genelde daha güvenilir.</p><p>NumPy'ın <code>std()</code>'u varsayılan olarak popülasyon standart sapmasını (n'e bölerek), pandas'ın <code>.std()</code>'u örneklem standart sapmasını (n − 1'e bölerek) hesaplar. Sonuçlar küçük de olsa farklı çıkar.</p>", "sirali": true},
  {"id": "w74", "dil": "python", "seviye": 3, "kategori": "Python Temelleri", "baslik": "Organizasyon seviyesi (sözlük ve while)", "soru": "Pandas'ın grup fonksiyonlarını kullanmadan, sözlük ve döngüyle her çalışanın organizasyondaki seviyesini bul: yöneticisi olmayan çalışan 1. seviye, ona bağlı olanlar 2. seviye, onlara bağlı olanlar 3. seviye… Sonucu <code>calisan</code> (ad soyad) ve <code>seviye</code> sütunlarıyla, seviyeye sonra ada göre sıralı bir DataFrame olarak <code>sonuc</code>'a ata.", "ipucu": "<code>dict(zip(EmployeeID, ReportsTo))</code> ile çalışan → yönetici sözlüğü kur. Her çalışan için yöneticisi kalmayana kadar <code>while</code> ile yukarı çık ve adımları say.", "cozum": "yonetici = dict(zip(Employees[\"EmployeeID\"], Employees[\"ReportsTo\"]))\nad = dict(zip(Employees[\"EmployeeID\"], Employees[\"FirstName\"] + \" \" + Employees[\"LastName\"]))\nsatirlar = []\nfor eid in Employees[\"EmployeeID\"]:\n    seviye, m = 1, yonetici[eid]\n    while pd.notna(m):\n        seviye += 1\n        m = yonetici[int(m)]\n    satirlar.append({\"calisan\": ad[eid], \"seviye\": seviye})\nsonuc = pd.DataFrame(satirlar).sort_values([\"seviye\", \"calisan\"])", "aciklama": "<p>SQL'de bu soru recursive CTE ile çözülür. Saf Python'da ise bir sözlük ve <code>while</code> döngüsü yeterli: her adımda bir üst yöneticiye geçip seviyeyi bir artırıyoruz, yönetici boş (NaN) olunca duruyoruz.</p><p><code>pd.notna(m)</code> eksik değeri kontrol ediyor. <code>ReportsTo</code> eksik değer içerdiği için pandas onu float yapar (2.0 gibi); sözlükte aramadan önce <code>int(m)</code> ile tam sayıya çeviriyoruz.</p><p>Andrew Fuller en tepede, 5 kişi doğrudan ona bağlı, 3 kişi de Steven Buchanan üzerinden 3. seviyede.</p>", "sirali": true},
  {"id": "w75", "dil": "python", "seviye": 3, "kategori": "Gruplama", "baslik": "Müşterinin sipariş geçmişi", "soru": "Siparişleri müşteri ve tarihe göre sırala. Her siparişin o müşterinin kaçıncı siparişi olduğunu (<code>kacinci</code>) ve bir önceki siparişten bu yana geçen gün sayısını (<code>ara_gun</code>) hesapla. ALFKI müşterisinin siparişlerini <code>OrderID</code>, <code>OrderDate</code>, <code>kacinci</code>, <code>ara_gun</code> sütunlarıyla <code>sonuc</code>'a ata.", "ipucu": "<code>groupby(\"CustomerID\").cumcount() + 1</code> sıra numarası verir, <code>groupby(...)[\"OrderDate\"].shift(1)</code> önceki siparişin tarihini getirir.", "cozum": "o = Orders.sort_values([\"CustomerID\", \"OrderDate\", \"OrderID\"]).copy()\no[\"kacinci\"] = o.groupby(\"CustomerID\").cumcount() + 1\no[\"onceki\"] = o.groupby(\"CustomerID\")[\"OrderDate\"].shift(1)\no[\"ara_gun\"] = (o[\"OrderDate\"] - o[\"onceki\"]).dt.days\nsonuc = o.loc[o[\"CustomerID\"] == \"ALFKI\", [\"OrderID\", \"OrderDate\", \"kacinci\", \"ara_gun\"]]", "aciklama": "<p><code>cumcount</code> grubun içinde 0'dan başlayan sıra numarası verir (SQL'deki <code>ROW_NUMBER() OVER (PARTITION BY ...)</code> − 1). <code>shift(1)</code> bir önceki satırın değerini getirir, grup içinde kullanınca başka müşterinin siparişine taşmaz (SQL'deki <code>LAG</code>).</p><p>Önce doğru sıralamak şart: <code>cumcount</code> ve <code>shift</code> satırların mevcut sırasını kullanır. Sıralamadan yapsaydık \"önceki sipariş\" rastgele bir sipariş olurdu.</p><p>ALFKI'nin 6 siparişi var. İlk siparişin önceki siparişi olmadığı için <code>ara_gun</code> boş. Siparişler arası süre 10 ile 94 gün arasında değişiyor.</p>", "sirali": true}
];
if (typeof module !== 'undefined') module.exports = { NW_SORULAR };
